/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A61 non-author staging only; exact manifest validator loads this file in mock and real registry. */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x,t='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType:t,type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs});
P('learner','Learner is formed from learn plus the agent suffix -er, naming a person acquiring a skill or subject knowledge.',C('learner.s1','语言学习','As a beginner learner of Mandarin, Rosa practised tones with a partner for ten minutes each morning.','作为普通话初学者，罗莎每天早晨和伙伴练习十分钟声调。','As a beginner learner of Mandarin / Rosa practised tones with a partner / for ten minutes each morning.','learner 指正在学习某项技能或学科的人；of Mandarin 指学习内容。','练习声调的学习者正在获得语言技能。'),M('The learner had never studied the language, yet the report described her as an experienced learner who had mastered every tone.','The learner was still practising the tones and had not mastered them yet.','初学且未掌握声调不能同时称为已精通所有声调的学习者。','context'),[Q('learner',1,1,'A learner is a person who is?','acquiring knowledge or a skill','teaching a class at a university','renting out a building','learner 指学习者。'),Q('learner',2,1,'What did Rosa practise each morning?','Mandarin tones','a legal lease','a political speech','她每天练习普通话声调。'),Q('learner',3,1,'Which person is a learner?','someone studying to play the violin','someone who has never tried or studied it','someone who leases the music hall','学习小提琴的人是 learner。'),Q('learner',4,1,'Learner is formed from learn plus?','-er','-ness','-ity','-er 在此表示学习的人。','word-formation')]);
P('learning','Learning combines learn with -ing and names either the process of gaining knowledge or the knowledge acquired through study.',[C('learning.s1','课堂与技能','The school values learning through experiments, allowing pupils to test ideas before memorising definitions.','这所学校重视通过实验来学习，让学生先检验想法，再记忆定义。','The school values learning through experiments / allowing pupils to test ideas / before memorising definitions.','learning.s1 指获取知识或技能的过程；through experiments 表示学习方式。','学生通过实践活动获得知识，体现过程义。'),C('learning.s2','学术与学识','Her learning in medieval history was evident in the careful notes she added to every archive catalogue.','她在中世纪史方面的学识，从她给每份档案目录所作的细致注释中可见一斑。','Her learning in medieval history was evident / in the careful notes / she added to every archive catalogue.','learning 可指通过研究获得的学识；in medieval history 限定知识领域。','深入研究留下专业而准确的注释，体现学识义。')],M('The school claimed that learning had improved, although pupils gained no knowledge or skill and could explain nothing new.','The school reported improved learning after pupils gained and applied new skills.','完全没有获得知识或技能，不支持“学习有所改善”的说法。','meaning'),[Q('learning',1,1,'Learning as a process means?','gaining knowledge or a skill','leasing a room for a fixed period','leaving a place for a holiday','learning.s1 指获取知识或技能的过程。'),Q('learning',2,2,'Her learning in history refers to her?','knowledge gained through study','ability to rent out an office','time away from work','learning.s2 可指学识。'),Q('learning',3,1,'Which activity is learning?','testing ideas in a science experiment','forgetting every new fact immediately','signing a lease agreement','实验中检验想法属于学习过程。'),Q('learning',4,2,'A scholar “of great learning” has?','extensive knowledge','a long leather leash','very little understanding','a person of learning 指有学识的人。')]);
P('lease','Lease entered English through Anglo-French and Latin legal forms related to letting property; it is a fixed-term rental contract or the act of granting use under one.',[C('lease.s1','住房与合同','Before moving into the flat, the tenants read the lease carefully and asked the landlord about the repair clause.','搬进公寓前，租户仔细阅读了租约，并向房东询问维修条款。','Before moving into the flat / the tenants read the lease carefully / and asked the landlord about the repair clause.','lease 作名词指约定期限内使用财产的法律合同；the repair clause 指具体条款。','租户阅读合同并询问其中条文。'),C('lease.s2','商业租赁','The company leases its ground-floor office to a dental clinic under a five-year agreement.','公司按五年协议把一楼办公室出租给一家牙科诊所。','The company leases its ground-floor office to a dental clinic / under a five-year agreement.','lease 作及物动词，lease property to someone 表示把财产租给某人。','公司向诊所提供办公室使用权并收取租金。')],M('The company leased the clinic’s office to the clinic, although the clinic already owned the building outright.','The company leased its office to the clinic under an agreed rental contract.','若诊所已经拥有建筑物，就不应写成公司把该处租给诊所。','context'),[Q('lease',1,1,'A lease is a legal agreement to?','use property for a stated period in return for payment','buy groceries for one afternoon','leave a job without notice','lease.s1 指租赁合同。'),Q('lease',2,2,'If a company leases an office to a clinic, it?','lets the clinic use the office under an agreement','moves the clinic to another city','gives the clinic ownership without conditions','lease 作动词可指出租。'),Q('lease',3,1,'Where would a tenant find the repair clause?','in the lease','on a leatherback turtle','inside a lecturer’s lecture','租约中会列出维修条款。'),Q('lease',4,2,'Which sentence uses lease as a verb?','They lease the shop to a baker.','They signed a lease for the shop.','The lease lasts five years.','第一句中 lease 是动词。')]);
P('leash','Leash 的词源不确定；名词义指牵狗用的带子或链条，动词义可比喻控制、约束某人或某种情绪。',[C('leash.s1','宠物与公共空间','The hiker kept the young dog on a leash near the cliff path so it would not run toward the edge.','徒步者在悬崖小径附近给小狗拴上牵引带，以免它跑向边缘。','The hiker kept the young dog on a leash / near the cliff path / so it would not run toward the edge.','on a leash 表示狗被牵引带拴着；so 引出这样做的目的。','牵住小狗能避免它跑到危险边缘。',''),C('leash.s2','情绪控制','During the tense hearing, the witness leashed her anger and answered each question calmly.','在紧张的听证会上，证人控制住怒气，平静地回答每个问题。','During the tense hearing / the witness leashed her anger / and answered each question calmly.','leash 作动词比喻控制情绪；leashed her anger 是“克制怒气”。','她控制愤怒并冷静作答。')],M('The owner kept the dog on a leash by removing the lead and letting it run freely beside traffic.','The owner kept the dog on a leash by holding its lead near the road.','放开牵引带任狗跑动，不是把狗拴着。','meaning'),[Q('leash',1,1,'A leash is usually used to?','lead or restrain a dog','teach a university lecture','measure the length of a leg','leash 名词指牵狗带。'),Q('leash',2,2,'To leash one’s anger is to?','keep it under control','make it grow stronger','leave it out of a contract','leash 可比喻克制情绪。'),Q('leash',3,1,'Why did the hiker keep the dog on a leash?','to stop it running toward the cliff edge','to let it roam near the edge unsupervised','to teach it to read a lecture','牵住狗是为了防止它冲向边缘。'),Q('leash',4,2,'Which use is figurative?','She leashed her temper during the hearing.','He clipped the lead to the dog’s collar.','The leash was made of leather.','克制 temper 使用动词的比喻义。')]);
P('least','Least is the superlative of little; it can mark the smallest amount or degree, function adverbially for “to the smallest extent,” or name a tiny amount.',[C('least.s1','数量比较','Of the three hikers, Mei carried the least water because she expected to refill her bottle at the spring.','三名徒步者中，梅带的水最少，因为她打算在泉边给水瓶补水。','Of the three hikers / Mei carried the least water / because she expected to refill her bottle at the spring.','the least 修饰不可数名词 water，表示数量最少；of the three 构成范围比较。','她带水量比其他两人少。'),C('least.s2','程度比较','The new route worries the guide least of all because its ledges are wide and well protected.','新路线最不让向导担心，因为那里的岩架宽阔且防护良好。','The new route worries the guide least of all / because its ledges are wide / and well protected.','least of all 作副词短语表示“尤其不、最不”；worries 的宾语是 guide。','宽阔并有防护的岩架让向导最不担心。'),C('least.s3','极少量与强调','I do not have the least doubt that the lecturer will explain the result clearly.','我丝毫不怀疑讲师会把结果解释清楚。','I do not have the least doubt / that the lecturer will explain the result clearly.','the least 可作限定词表示极小的数量；not the least doubt 强调完全不怀疑。','说话者明确表示一点也不怀疑。')],M('She carried the least water of all three hikers, so her bottle held more than either of the others.','She carried the least water of all three hikers, so her bottle held less than either of the others.','“最少”表示数量低于其余比较对象。','meaning'),[Q('least',1,1,'The least water means?','the smallest amount of water','more water than anyone else','water with the most leather','least.s1 指最少的数量。'),Q('least',2,2,'“It worries her least of all” means it worries her?','to the smallest degree','more than every other issue','only during a lecture','least of all 表示最不、程度最低。'),Q('least',3,3,'“I do not have the least doubt” means?','I have no doubt at all','I have a very large doubt','I have only one question','the least doubt 强调丝毫不怀疑。'),Q('least',4,1,'Least is the superlative form of?','little','leather','left','little 的最高级是 least。')]);
P('leather','Leather comes through Old English lether from a Germanic source; it names treated animal skin and, in the plural, clothes or goods made from it.',[C('leather.s1','材料与制品','The artisan chose vegetable-tanned leather for the satchel because it would soften with use.','工匠为挎包选了植鞣皮革，因为这种皮革会越用越柔软。','The artisan chose vegetable-tanned leather for the satchel / because it would soften / with use.','leather.s1 指经过处理、可制作物品的动物皮；leather 作材料名词通常不可数。','制包使用的植鞣皮革体现材料义。'),C('leather.s2','服饰与骑行','The motorcyclist wore black leathers and a reinforced jacket for the long ride.','摩托车手穿着黑色皮衣和加固夹克开始长途骑行。','The motorcyclist wore black leathers / and a reinforced jacket / for the long ride.','leathers 作复数名词可指皮衣或皮制装备；wore 表示穿着。','骑行者穿着成套皮制服装。')],M('The satchel was made of leather, but the label described the leather as a type of fresh vegetable.','The satchel was made of treated animal skin called leather.','leather 是加工后的动物皮革，不是蔬菜。','meaning'),[Q('leather',1,1,'Leather is material made from?','treated animal skin','fresh green onions','a turtle’s hard shell only','leather 指经过处理的动物皮。'),Q('leather',2,2,'Black leathers in a motorcycling context are?','leather clothes or protective gear','a collection of vegetables','several legal contracts','leathers 可指皮衣或皮制装备。'),Q('leather',3,1,'Why did the artisan choose vegetable-tanned leather?','it would soften with use','it was a type of lecture','it was already a finished satchel','植鞣皮革会随着使用变软。'),Q('leather',4,2,'Which phrase uses leather as material?','a bag made of leather','a rider wearing leathers','several leathers hanging on a rack','made of leather 指材料；wearing leathers 指皮衣。')]);
P('leatherback','Leatherback combines leather and back, describing the sea turtle whose tough, ridged skin covers its back instead of a shell made of hard plates.',C('leatherback.s1','海洋生物','The leatherback crossed the bay on its way to a nesting beach, surfacing briefly before diving again.','棱皮龟游过海湾前往产卵海滩，短暂浮出水面后又潜入水中。','The leatherback crossed the bay / on its way to a nesting beach / surfacing briefly before diving again.','leatherback 是大型海龟名，完整名称常写 leatherback turtle；surfacing 表示浮出水面。','游过海湾并前往海滩产卵的是棱皮龟。'),M('The leatherback was a small land tortoise with a rigid shell made of neatly arranged hard plates.','The leatherback was a large sea turtle with tough, ridged skin over its back.','棱皮龟是大型海龟，背甲由韧皮形成棱脊，不是小型陆龟的骨板壳。','meaning'),[Q('leatherback',1,1,'A leatherback is the largest kind of?','sea turtle','land leopard','leek','leatherback 是大型海龟。'),Q('leatherback',2,1,'What is unusual about its back covering?','tough ridged skin rather than hard plates','soft feathers rather than scales','a pouch for carrying a joey','棱皮龟的背部是有棱的韧皮。'),Q('leatherback',3,1,'Where was the turtle heading?','a nesting beach','a university lecture hall','a legal legislature','它正前往产卵海滩。'),Q('leatherback',4,1,'Leatherback is named from leather-like skin on its?','back','left wing','lens','词名指向其皮革状背部。')]);
P('leathery','Leathery is formed from leather plus -y, describing something tough or wrinkled like leather, including skin, leaves, or food.',C('leathery.s1','质地与植物','The old olive leaves felt leathery, with a tough surface that resisted tearing in the dry wind.','老橄榄叶摸起来像皮革一样坚韧，表面很硬，在干风中不易撕裂。','The old olive leaves felt leathery / with a tough surface / that resisted tearing in the dry wind.','leathery 是形容词，描述皮革般坚韧或粗硬的质地；that 指 surface。','叶片韧硬、不易撕裂，符合 leathery 的触感义。'),M('The leathery leaves were soft and watery, tearing apart at the lightest touch.','The leathery leaves were tough and resisted tearing.','柔软易碎与 leathery 的坚韧质地相反。','meaning'),[Q('leathery',1,1,'A leathery surface feels?','tough and somewhat like leather','soft and full of water','thin like a sheet of paper only','leathery 表示皮革般坚韧。'),Q('leathery',2,1,'Why were the olive leaves described as leathery?','their tough surface resisted tearing','they were made from animal hide','they had no surface at all','叶片坚韧不易撕裂。'),Q('leathery',3,1,'Which object might be leathery?','an old, tough leaf','a fresh cup of water','a smooth legal clause','硬韧的老叶可以形容为 leathery。'),Q('leathery',4,1,'Leathery is formed from leather plus?','-y','-ship','-let','leathery 由 leather 加 -y 构成。','word-formation')]);
P('leave','Leave developed from Old English verbs meaning to depart or let remain; it can mean go away, allow something to stay, forget something behind, stop a job or school, or an authorized period away from work.',[C('leave.s1','出发与离开','The last ferry leaves the island at six, so visitors must reach the pier before sunset.','最后一班渡轮六点离岛，因此游客必须在日落前到达码头。','The last ferry leaves the island at six / so visitors must reach the pier / before sunset.','leave 作不及物或及物动词表示离开某地；the island 是离开的地点。','渡轮从岛上出发，体现离开义。'),C('leave.s2','保持状态','Please leave the side gate unlocked so the delivery team can bring the boxes inside.','请让侧门保持未上锁，这样配送人员就能把箱子搬进来。','Please leave the side gate unlocked / so the delivery team / can bring the boxes inside.','leave + 宾语 + 形容词表示让某物保持某种状态；unlocked 是宾补。','要求让门保持未锁，体现“留下某状态”义。'),C('leave.s3','落下物品','I left my reading glasses on the lecture-room desk and had to return after class.','我把眼镜落在讲堂的桌上，下课后只得回去取。','I left my reading glasses on the lecture-room desk / and had to return / after class.','leave 可指离开时忘了带走某物；left 是 leave 的过去式。','眼镜留在原处而未随身带走。'),C('leave.s5','休假与准假','The nurse is on leave this week and will return to the clinic on Monday.','护士本周休假，周一回诊所上班。','The nurse is on leave this week / and will return to the clinic / on Monday.','leave 作名词指获准离开工作的假期；on leave 是固定搭配。','护士暂时不工作并会按时返岗，体现休假义。')],M('I left my glasses at home, but they were in my bag with me throughout the lecture.','I brought my glasses to the lecture in my bag and did not leave them at home.','若眼镜一直随身携带，就不是把它们落在家里。','meaning'),[Q('leave',1,1,'When a ferry leaves the island, it?','goes away from the island','stays tied to the pier all day','rents the island to visitors','leave.s1 指离开。'),Q('leave',2,2,'“Leave the gate unlocked” means?','allow it to remain unlocked','lock it immediately','remove the gate from its hinges','leave.s2 表示让门保持未锁状态。'),Q('leave',3,3,'If you left your glasses in the lecture room, you?','went away without taking them','carried them home in your pocket','gave them to the lecturer permanently','leave.s3 可指离开时忘拿某物。'),Q('leave',4,5,'If a nurse is on leave, she is?','taking authorized time away from work','resigning permanently','giving a lecture to patients','on leave 指休假。')]);
P('leave out','Leave out is a phrasal verb formed from leave plus out; it means not to include something or to omit it.',C('leave out.s1','编辑与清单','The editor left out the final paragraph because it repeated a point already made on the previous page.','编辑删去了最后一段，因为它重复了前一页已经说过的观点。','The editor left out the final paragraph / because it repeated a point / already made on the previous page.','leave out 是可分短语动词，left out 后接被省略的内容；left 是过去式。','重复内容被有意省略。'),M('The editor left out the final paragraph by printing it in full at the end of the article.','The editor included the final paragraph and did not leave it out.','完整刊出该段表示 include，与 leave out“省略”相反。','meaning'),[Q('leave out',1,1,'To leave out a detail is to?','omit it or not include it','explain it at greater length','leave a building with it','leave out 指省略或遗漏。'),Q('leave out',2,1,'Why did the editor leave out the paragraph?','it repeated an earlier point','it introduced completely new evidence','the paragraph was a legal lease','重复内容被省略。'),Q('leave out',3,1,'Which sentence uses leave out correctly?','Do not leave out the date on the form.','Do not leave the date out of at home.','Do not out leave the date.','leave out 可接宾语，也可写 leave the date out。'),Q('leave out',4,1,'Leave out is closest in meaning to?','omit','include','lecture','omit 与 leave out 同义。')]);
P('leaver','Leaver is formed from leave plus the agent suffix -er and names a person departing a school, job, or place, especially a school leaver.',C('leaver.s1','教育与升学','The school held a careers fair for its leavers, helping them compare apprenticeships and college courses.','学校为离校生举办职业展，帮助他们比较学徒岗位和大学课程。','The school held a careers fair for its leavers / helping them compare / apprenticeships and college courses.','leaver 指离校、离职或离开某地的人；school leavers 常指离校学生。','离校学生正在考虑后续教育和职业路径。'),M('The leaver was described as a new pupil who had just joined the school and had never left it.','The leaver was a student finishing school and preparing for the next step.','刚入学且尚未离校的学生不是 school leaver。','word-choice'),[Q('leaver',1,1,'A school leaver is someone who?','is leaving school','is beginning the first day of school','teaches a university lecture','school leaver 指离校学生。'),Q('leaver',2,1,'What did the careers fair help leavers compare?','apprenticeships and college courses','different kinds of leather','leeks from several farms','离校生比较升学和学徒机会。'),Q('leaver',3,1,'Leaver is formed from leave plus?','-er','-ity','-ous','leaver 由 leave 加 -er 构成。','word-formation'),Q('leaver',4,1,'Which person is a leaver?','an employee departing a company','a lecturer who stays to teach','a learner starting a new course','离开公司的人是 leaver。')]);
P('lecture','Lecture entered English through Latin and French forms related to reading aloud; it can be a prepared educational talk, a serious scolding, or the act of teaching or reprimanding.',[C('lecture.s1','大学课堂','Professor Malik gave a lecture on migration history, using old maps to trace how families moved across the region.','马利克教授作了一场移民史讲座，用旧地图追踪各个家庭如何迁徙。','Professor Malik gave a lecture on migration history / using old maps / to trace how families moved across the region.','lecture 作可数名词指面向听众的长篇讲授；give a lecture on 是常见搭配。','教授围绕学科主题向学生作系统讲授。'),C('lecture.s2','劝诫与训斥','After he ignored the safety rules, his supervisor gave him a lecture about wearing protective glasses.','他无视安全规定后，主管就佩戴防护眼镜一事训了他一顿。','After he ignored the safety rules / his supervisor gave him a lecture / about wearing protective glasses.','give someone a lecture about 可指严肃训斥；about 引出被批评的问题。','主管长篇批评员工不遵守安全规定。')],M('The professor gave a lecture by refusing to speak to the students and showing no material about the subject.','The professor gave a lecture by explaining the subject to the students.','完全没有讲授或向学生呈现内容，不构成 lecture。','meaning'),[Q('lecture',1,1,'A university lecture is usually?','a prepared talk that teaches a subject','a short note left on a desk','a legal contract for renting a flat','lecture.s1 是教学讲座。'),Q('lecture',2,2,'If a supervisor gives someone a lecture about safety, the supervisor?','scolds or seriously advises them','offers them a paid holiday','leaves out the safety rules','lecture.s2 指训斥或严肃告诫。'),Q('lecture',3,3,'“She lectures on economics” means she?','teaches economics through lectures','attends one lecture as a student','rents an office to an economist','lecture.s3 作动词表示讲授。'),Q('lecture',4,4,'“Do not lecture me about my habits” means?','do not scold or preach to me','do not teach me any university subject','do not leave the room','lecture.s4 表示长篇批评或说教。')]);
P('lecturer','Lecturer is formed from lecture plus -er; it names a person who gives lectures, especially a university teacher in British English.',C('lecturer.s1','高等教育','The lecturer paused after each diagram so that students could copy the labels before the next explanation.','讲师在每张示意图后停顿，让学生抄下标注再听下一段讲解。','The lecturer paused after each diagram / so that students could copy the labels / before the next explanation.','lecturer 指讲课的人，尤指大学教师；so that 引出停顿的教学目的。','教师讲授材料并留出时间让学生记录。'),M('The lecturer gave no lessons or talks and worked only as a student in the audience.','The lecturer explained the diagrams to the class and gave students time to take notes.','只作为听众的学生不是负责讲课的 lecturer。','meaning'),[Q('lecturer',1,1,'A lecturer is especially likely to teach at?','a university','a dog kennel','a leather workshop only','lecturer 尤指大学讲师。'),Q('lecturer',2,1,'Why did the lecturer pause after each diagram?','so students could copy the labels','so the students would leave out every label','so the lecture could become a lease','停顿是为了让学生记录图示标签。'),Q('lecturer',3,1,'Which word names the person giving a lecture?','lecturer','leaver','lessee','lecturer 指讲课者。'),Q('lecturer',4,1,'Lecturer is formed from lecture plus?','-er','-ship','-less','-er 表示从事讲课的人。','word-formation')]);
P('ledge','Ledge comes through Middle English from an Old English word for a border or projecting edge; it names a narrow, flat surface on a wall or rock face.',C('ledge.s1','建筑与地貌','A row of small pots lined the window ledge, where they received enough light but stayed out of the walkway.','一排小花盆摆在窗台上，那里光线充足，也不妨碍通道。','A row of small pots lined the window ledge / where they received enough light / but stayed out of the walkway.','ledge 指墙边或岩壁上狭窄平坦的凸出部分；where 指窗台位置。','窗台是墙上的狭长平面，能放置花盆。'),M('The pot stood on a window ledge, a deep open room with no projecting flat surface.','The pot stood on a narrow flat shelf projecting from the wall beneath the window.','ledge 是凸出的窄平面，不是没有平面支撑的房间。','meaning'),[Q('ledge',1,1,'A ledge is a narrow, flat surface on a?','wall or rock face','leek leaf only','legal document','ledge 指墙壁或岩面上的窄平台。'),Q('ledge',2,1,'Where were the pots placed?','on the window ledge','inside the lecture notes','under the turtle’s pouch','花盆放在窗台上。'),Q('ledge',3,1,'Which surface could be a ledge?','a small shelf projecting from a cliff','a broad flat field with no raised edge','a leather bag carried on the back','岩壁凸出的狭窄平台是 ledge。'),Q('ledge',4,1,'A window ledge can hold?','small pots','a university degree','a legal legislature','窗台可摆放花盆等物品。')]);
P('leek','Leek is a Germanic vegetable name related to Old English lēac; it refers to a long onion-like vegetable and is also a national emblem of Wales.',[C('leek.s1','烹饪与蔬菜','The cook sliced the leek lengthwise, rinsed the grit from its layers, and added it to the soup.','厨师把韭葱纵向切开，冲掉叶层间的沙土，再放进汤里。','The cook sliced the leek lengthwise / rinsed the grit from its layers / and added it to the soup.','leek 指味道像洋葱的长形蔬菜；slice lengthwise 表示纵向切开。','清洗叶层并放入汤中，是韭葱的食用场景。'),C('leek.s2','威尔士文化','On St David’s Day, some Welsh schoolchildren wear a leek as a national emblem.','在圣大卫日，一些威尔士学生会佩戴韭葱作为民族象征。','On St David’s Day / some Welsh schoolchildren wear a leek / as a national emblem.','leek 也指威尔士的民族象征；as 表示佩戴它的象征身份。','韭葱常作为威尔士文化标志。')],M('The recipe called for leek, but the cook added a sweet fruit with no onion-like flavour.','The recipe called for leek, so the cook added the long green onion-like vegetable.','用味道不像洋葱的水果替代韭葱不符合食谱所指蔬菜。','meaning'),[Q('leek',1,1,'A leek is a long green vegetable related to?','onions','leopards','lectures','leek 是类似大型洋葱的蔬菜。'),Q('leek',2,2,'What can a leek symbolize in Wales?','Welsh national identity','a legal lease','a university lecturer','韭葱是威尔士的民族象征。'),Q('leek',3,1,'How did the cook prepare the leek?','sliced it lengthwise and rinsed its layers','left it in a leather bag','used it as a desk ledge','例句中厨师切开并清洗韭葱。'),Q('leek',4,2,'On which occasion might a Welsh child wear a leek?','St David’s Day','a lecture on leprosy','a lease signing','圣大卫日有佩戴韭葱的传统。')]);
P('leeway','Leeway originally described room for a ship to drift to leeward; it now means freedom or margin to act within limits.',C('leeway.s1','计划与时间','The project manager built two days of leeway into the schedule in case the supplier delivered the glass late.','项目经理在日程中留出两天余量，以防供应商延迟交付玻璃。','The project manager built two days of leeway into the schedule / in case the supplier delivered the glass late.','leeway 指限度内可调整的余地或余量；in case 引出预防的情况。','预留时间可吸收交货延误，体现计划余量。'),M('The schedule left no leeway, yet the team claimed it could delay the deadline by several weeks without asking anyone.','The schedule left a little leeway, allowing a short delay if the glass arrived late.','若日程没有余地，团队不能自行延后数周而无需协调。','meaning'),[Q('leeway',1,1,'Leeway in a schedule is?','room for adjustment or delay','a fixed deadline with no flexibility','a narrow ledge on a wall','leeway 指时间安排中的余地。'),Q('leeway',2,1,'Why did the manager allow two days of leeway?','the supplier might deliver late','the glass was already installed','the project had no schedule','留出余量是为应对可能的延迟。'),Q('leeway',3,1,'Which rule gives employees leeway?','staff may adjust the start time within a one-hour window','everyone must arrive at the exact same second','no one may change any part of the schedule','可在范围内调整开始时间，说明有余地。'),Q('leeway',4,1,'Leeway is closest in meaning to?','latitude or margin','lecture or lesson','leather or hide','latitude 和 margin 都可表示余地。')]);
P('left','Left is related to Old English lyft, “weak” or “unlucky,” and functions as an adjective, adverb, or noun for the left side; it also means remaining and names the political left.',[C('left.s1','方向与路线','At the next junction, turn left and follow the signs toward the river station.','到下一个路口向左转，然后沿路标前往河边车站。','At the next junction / turn left / and follow the signs toward the river station.','left 作副词指向左侧转弯；turn left 是常见方向指令。','按指示向左转即可到达车站。'),C('left.s3','剩余与数量','There are three seats left in the lecture hall, so the late arrivals can still sit together.','讲堂里还剩三个座位，因此迟到的人仍可坐在一起。','There are three seats left in the lecture hall / so the late arrivals / can still sit together.','left 作形容词表示剩下的，常置于名词后；three seats left 指尚未占用的座位。','仍有空座，体现剩余义。'),C('left.s4','政治立场','The party’s left supports stronger public housing programs and more protections for low-income workers.','该党左翼支持更强的公共住房计划，并主张加强对低收入劳动者的保护。','The party’s left supports stronger public housing programs / and more protections / for low-income workers.','the left 作名词指政治左派或左翼；supports 是单数集合表达。','政策倾向对应政治左翼义。')],M('Turn left at the junction, then continue toward the river on the right-hand road as instructed.','Turn right at the junction, then continue toward the river on the right-hand road.','前后指令若均为右转，就不能说在路口向左转。','meaning'),[Q('left',1,1,'To turn left is to move toward the side opposite?','the right','the front','the sky','left.s1 指左侧方向。'),Q('left',2,3,'“The party’s left” refers to?','the party’s political wing favoring social change','seats remaining in a hall','a direction on a map only','left.s4 指政治左翼。'),Q('left',3,3,'“Three seats are left” means?','three seats remain available','three seats have been removed','three seats face the left wall','left.s3 表示剩下。'),Q('left',4,1,'Which sentence uses left as a direction?','Turn left after the bridge.','There is one seat left.','She belongs to the political left.','第一句的 left 表示方向。')]);
P('left wing','Left wing combines left with wing and names the politically left-wing section of a party or movement, often supporting social reform or a larger public role.',C('left wing.s1','政党与政策','The left wing of the party pushed for stronger tenant protections during the housing debate.','住房辩论期间，该党的左翼推动加强租户保护。','The left wing of the party pushed for stronger tenant protections / during the housing debate.','left wing 作名词短语指政党中的左翼派别；of the party 表示所属。','推动租户保护体现该派的政策主张。'),M('The party’s left wing opposed every proposal for social reform and called for less public support.','The party’s left wing supported the proposed social reforms and stronger public services.','反对全部社会改革与该语境中的左翼政策取向相反。','meaning'),[Q('left wing',1,1,'The left wing of a political party is?','the faction on the political left','the party’s aircraft division','the side of a building facing west','left wing 指政治左翼。'),Q('left wing',2,1,'What did the party’s left wing support?','stronger protections for tenants','removing all housing protections','a new leather factory','例句表明左翼推动租户保护。'),Q('left wing',3,1,'Which topic is most likely to involve a party’s left wing?','social and economic policy','the shape of a turtle’s shell','the length of a lecture','左翼常出现在政治和经济政策讨论中。'),Q('left wing',4,1,'Left wing is a political?','group or faction','legal contract','vegetable','left wing 指政治派别。')]);
P('left-hand side','Left-hand side is formed from left, hand, and side; it names the side of an object or space that lies to the left when viewed from the stated position.',C('left-hand side.s1','位置与说明','The emergency stop is on the left-hand side of the machine, beside the red indicator light.','紧急停止按钮在机器左侧，位于红色指示灯旁边。','The emergency stop is on the left-hand side of the machine / beside the red indicator light.','on the left-hand side of 表示在某物的左侧；of the machine 指参照物。','按钮位于机器左边，符合方向短语。'),M('The label said the emergency stop was on the left-hand side, but the button was located on the far right.','The label said the emergency stop was on the right-hand side, matching the button’s actual position.','若按钮实际在右侧，就不应说它位于左侧。','meaning'),[Q('left-hand side',1,1,'The left-hand side is?','the side on the left','the upper edge','the side behind a person only','left-hand side 指左侧。'),Q('left-hand side',2,1,'Where was the emergency stop?','beside the red light on the machine’s left','on the machine’s far right','under the floor of the lecture hall','按钮在机器左侧。'),Q('left-hand side',3,1,'Which preposition commonly introduces this phrase?','on','under of','into at','常说 on the left-hand side。'),Q('left-hand side',4,1,'The reference object in “left-hand side of the machine” is?','the machine','the red light only','the emergency stop operator','of the machine 指方向参照物。')]);
P('leftover','Leftover combines left, in the sense “remaining,” with over; it can be a noun for something unused, especially food, or an adjective for what remains.',[C('leftover.s1','食物与储存','We packed the leftovers into sealed containers and labelled each one with the date.','我们把剩菜装进密封盒，并在每盒上标注日期。','We packed the leftovers into sealed containers / and labelled each one / with the date.','leftovers 常作复数名词指剩菜；pack into 表示装入容器。','吃剩的食物被保存以供之后食用。'),C('leftover.s2','材料与修补','She used leftover fabric from the curtains to patch a tear in the cushion cover.','她用窗帘剩下的布料补了靠垫套上的裂口。','She used leftover fabric from the curtains / to patch a tear / in the cushion cover.','leftover 作形容词修饰 fabric，表示使用后剩余的材料。','缝补时使用未用完的布料。')],M('She used leftover fabric, meaning fabric that had not yet been used and was still available, but claimed none remained.','She used the leftover fabric that remained after the curtains were made.','若布料已经全部用完，就没有 leftover fabric 可供使用。','meaning'),[Q('leftover',1,1,'Leftovers at lunch are?','food remaining from an earlier meal','a lecture prepared for students','a legal document for renting a flat','leftovers 常指剩菜。'),Q('leftover',2,2,'Leftover fabric is fabric that?','remains after the main project uses some','was never part of the project','is made from a leatherback shell','leftover 作形容词表示剩余的。'),Q('leftover',3,1,'What did the family put into sealed containers?','food left from the meal','new curtains just purchased','a lecturer’s notes','剩菜被装进密封盒。'),Q('leftover',4,2,'Which phrase uses leftover as an adjective?','leftover paint in the tin','eat the leftovers','the leftovers were cold','leftover paint 中 leftover 修饰 paint。')]);
P('leftovers','Leftovers is the plural of leftover, naming food or other things remaining after the rest has been used.',C('leftovers.s1','食品保存','After the family picnic, Mara packed the leftovers into a cool box and labelled them for lunch the next day.','家庭野餐结束后，玛拉把剩菜装进保冷箱，并贴上标签留作第二天的午餐。','After the family picnic / Mara packed the leftovers into a cool box / and labelled them for lunch the next day.','leftovers 作复数名词指剩余食物；them 回指 leftovers。','未吃完的食物被保存起来之后再吃。'),M('They packed the leftovers before anyone had eaten the meal, so nothing had actually remained.','They packed the leftovers after the meal, saving the food that had not been eaten.','尚未开餐时没有剩余食物可称为 leftovers。','meaning'),[Q('leftovers',1,1,'Leftovers are usually?','food remaining after a meal','food served before anyone eats','a legal document about renting property','leftovers 指一餐后剩下的食物。'),Q('leftovers',2,1,'Why did Mara put them in a cool box?','to save the remaining food for later','to turn the food into leather','to leave out the lunch','她保存剩菜供第二天食用。'),Q('leftovers',3,1,'Which item is a leftover?','the uneaten rice from last night’s dinner','a fresh meal that has not been served','a lecture scheduled for tomorrow','剩下未吃的米饭是 leftover。'),Q('leftovers',4,1,'Leftovers is normally used in which form?','plural','singular only','as an adjective before every noun','leftovers 通常以复数形式指剩菜。')]);
P('leg','Leg comes through Old Norse leggr, “limb”; it can name a body limb, a trouser part, one section of a journey, or a furniture support.',[C('leg.s1','身体与运动','The runner stretched each leg carefully before starting the uphill race.','跑者在开始爬坡比赛前仔细拉伸了双腿。','The runner stretched each leg carefully / before starting / the uphill race.','leg.s1 指身体下肢；each 后接单数名词 leg。','跑者拉伸身体肢体以做好运动准备。'),C('leg.s2','服装与修补','A tear in the left leg of his trousers appeared after he caught it on the fence.','他的裤子左裤腿挂到围栏后撕开了一道口子。','A tear in the left leg of his trousers appeared / after he caught it / on the fence.','leg 可指裤子覆盖腿部的部分；left leg of his trousers 是裤腿。','破损发生在裤子的左裤腿上。'),C('leg.s3','旅程分段','The first leg of the journey was by train, with a short ferry crossing at the end.','旅程的第一段乘火车，末尾再短暂乘一段渡轮。','The first leg of the journey was by train / with a short ferry crossing / at the end.','leg 可指旅程或比赛的一段；the first leg 标记第一程。','长途旅行由不同交通阶段构成。'),C('leg.s4','家具结构','One leg of the kitchen table was loose, so Sam tightened the screw before dinner.','厨房桌子的一条桌腿松了，所以萨姆在晚餐前拧紧了螺丝。','One leg of the kitchen table was loose / so Sam tightened the screw / before dinner.','leg 可指家具的细长支撑部分；of the kitchen table 表示所属。','桌子一条支撑腿松动需要加固。')],M('The table stood on four legs, but the report called its legs the fabric sleeves covering trousers.','The table stood on four legs, each a support attached beneath the tabletop.','桌腿是家具支撑部件，不是裤子的布料部分。','meaning'),[Q('leg',1,1,'A person’s leg is one of the body’s?','lower limbs','furniture joints','legal agreements','leg.s1 指身体下肢。'),Q('leg',2,2,'A trouser leg is?','the part of the trousers covering a leg','a section of a train journey','one side of a political party','leg.s2 指裤腿。'),Q('leg',3,3,'The first leg of a trip is?','one part or stage of the journey','the traveler’s left limb','a table support','leg.s3 指旅程中的一段。'),Q('leg',4,4,'Which use refers to furniture?','The chair has a broken leg.','He injured his leg.','The first leg ends in Paris.','家具的支撑部件也叫 leg。')]);
P('legacy','Legacy comes through French from Latin legatum, “something bequeathed”; it can mean property left by a will or an influence that remains after an event.',[C('legacy.s1','遗嘱与捐赠','The scientist left a legacy to the university so that future learners could use the new laboratory.','这位科学家给大学留下了一笔遗赠，让未来的学习者可以使用新实验室。','The scientist left a legacy to the university / so that future learners / could use the new laboratory.','legacy.s1 指遗嘱中留下的钱或财产；leave a legacy to someone 是常见结构。','遗赠用于支持大学和后续学习。'),C('legacy.s2','历史影响','The old factory’s legacy is a network of apprenticeships that still trains skilled workers today.','旧工厂留下的遗产是一套至今仍在培养熟练工人的学徒培训网络。','The old factory’s legacy is a network of apprenticeships / that still trains skilled workers / today.','legacy 可指事件或个人留下的持续影响或制度；is a network 解释此处的遗产。','工厂已经不在，但培训体系仍然延续。')],M('The factory’s legacy vanished as soon as it closed, although its apprenticeship program continues to train workers today.','The factory’s legacy continues through its apprenticeship program, which still trains workers.','仍在运作的培训项目表明影响延续，不能说遗产已经消失。','meaning'),[Q('legacy',1,1,'A legacy in a will is?','money or property left to someone','a section of a journey','a narrow wall ledge','legacy.s1 指遗嘱留下的财产。'),Q('legacy',2,2,'A factory’s lasting legacy may be?','an influence or institution that continues after it closes','only the building’s lease payment','a lesson delivered by a lecturer','legacy.s2 指持续的历史影响。'),Q('legacy',3,1,'What did the scientist leave to the university?','a bequest supporting a laboratory','a leather leash','a political left wing','科学家留下了一笔遗赠。'),Q('legacy',4,2,'Which phrase describes a continuing effect?','the legacy of the old training program','the first leg of a journey','a legal lecture at noon','legacy 可表示延续至今的影响。')]);
P('legal','Legal derives from Latin legalis, based on lex “law”; it means permitted or required by law, or connected with law and lawyers.',[C('legal.s1','法规与许可','The sign explains whether overnight parking is legal on this street during winter.','这块标牌说明冬季在这条街上过夜停车是否合法。','The sign explains / whether overnight parking is legal / on this street during winter.','legal.s1 表示法律允许或禁止；whether 引出是否合法的问题。','查阅标牌判断行为是否符合法律。'),C('legal.s2','专业服务','The tenants sought legal advice before signing the long-term lease.','租户在签署长期租约前寻求了法律意见。','The tenants sought legal advice / before signing / the long-term lease.','legal.s2 表示与法律或律师有关，修饰 advice。','租户签合同前向法律专业人士咨询。')],M('The tenants sought legal advice from a pastry chef who had no knowledge of law or legal practice.','The tenants sought legal advice from a qualified lawyer before signing the lease.','与法律无关且无相关资质的人不能提供专业法律意见。','meaning'),[Q('legal',1,1,'If parking is legal, it is?','allowed by law','a political legend','a type of leather','legal.s1 指法律允许。'),Q('legal',2,2,'Legal advice is advice?','connected with law or lawyers','about preparing leeks','about a journey’s first leg','legal.s2 指法律方面的。'),Q('legal',3,1,'What did the sign explain?','whether overnight parking was allowed','how to write a lecture','where to buy a leatherback','标牌解释停车是否合法。'),Q('legal',4,2,'Which phrase uses legal in the law-related sense?','legal advice','legal parking limit','legal to park here','legal advice 是“法律意见”。')]);
P('legality','Legality combines legal with the noun suffix -ity and means the quality or status of being allowed by law.',C('legality.s1','法庭与程序','The judge questioned the legality of the search because officers had entered the flat without a warrant.','法官质疑搜查是否合法，因为警员没有搜查令便进入公寓。','The judge questioned the legality of the search / because officers had entered the flat / without a warrant.','legality 指行为在法律上是否被允许；the legality of 是常见结构。','是否持有搜查令决定该搜查的合法性问题。'),M('The court confirmed the legality of the search while ruling that it had clearly violated the law.','The court questioned the legality of the search because officers lacked a warrant.','如果搜查明显违反法律，法院就不会确认其合法性。','meaning'),[Q('legality',1,1,'The legality of an action concerns whether it is?','allowed by law','popular with a political party','easy to read','legality 指合法性。'),Q('legality',2,1,'Why did the judge question the search’s legality?','officers entered without a warrant','the flat had a leather door','the judge had left the court','没有搜查令引发合法性疑问。'),Q('legality',3,1,'Which phrase is natural?','question the legality of the search','question the legal of the search','question the legality to the search','常用结构是 the legality of。'),Q('legality',4,1,'Legality is formed from legal plus?','-ity','-er','-less','legality 由 legal 加 -ity 构成。','word-formation')]);
P('legalize','Legalize is formed from legal plus the verb-forming suffix -ize; it means to change the law so that an activity becomes permitted.',C('legalize.s1','公共政策','The parliament voted to legalize the treatment after reviewing medical evidence and consulting patient groups.','议会审阅医学证据并咨询患者团体后，投票决定使这种治疗合法化。','The parliament voted to legalize the treatment / after reviewing medical evidence / and consulting patient groups.','legalize 是及物动词，指通过法律使原本不合法的事物变合法；to legalize 后接宾语。','议会投票改变法律状态，符合合法化的意思。'),M('The law legalized the treatment by banning it and imposing criminal penalties on every patient.','The law legalized the treatment by allowing it under defined conditions.','禁止治疗并处罚患者表示非法化，而不是使其合法。','meaning'),[Q('legalize',1,1,'To legalize an activity is to?','make it lawful','make it difficult to read','leave it out of a lecture','legalize 指通过法律使合法。'),Q('legalize',2,1,'What did parliament review before the vote?','medical evidence and patient views','the length of a leather leash','a map legend only','议会在投票前审阅证据并咨询患者。'),Q('legalize',3,1,'Which sentence uses legalize correctly?','The bill would legalize the practice under clear rules.','The bill would legalize the practice by banning it.','The bill would legalize to the practice.','合法化意味着允许该行为。'),Q('legalize',4,1,'Legalize is formed from legal plus?','-ize','-ship','-less','-ize 可构成动词 legalize。','word-formation')]);
P('legally','Legally is formed from legal plus -ly and means according to law or in a way permitted by law.',[C('legally.s1','法律身份','The couple are legally married, although their private ceremony took place several months earlier.','这对伴侣在法律上已经结婚，尽管他们的私人仪式是在几个月前举行的。','The couple are legally married / although their private ceremony / took place several months earlier.','legally married 指婚姻已获法律承认；although 对照法律身份与仪式时间。','他们的婚姻身份在法律上有效。'),C('legally.s2','行为合法性','Visitors may fish legally in the lake only if they hold a current permit.','游客只有持有有效许可证，才能在湖里合法垂钓。','Visitors may fish legally in the lake / only if they hold / a current permit.','legally 修饰 fish，表示该行为须符合法律许可；only if 引出条件。','持有效许可证是依法垂钓的条件。')],M('The visitor fished legally without a permit in a lake where all fishing was prohibited.','The visitor fished legally after obtaining the required permit.','禁止垂钓且没有许可证的行为不合法。','context'),[Q('legally',1,1,'Legally married means?','recognized as married under the law','married only in a private ceremony','legally related to a lecture','legally.s1 指法律承认的婚姻关系。'),Q('legally',2,2,'When may visitors fish legally in the lake?','when they hold a current permit','whenever they ignore the fishing rules','only after leaving the lake','legally.s2 指依法做某事。'),Q('legally',3,1,'Legally is the adverb related to?','legal','leather','legend','legally 由 legal 派生。'),Q('legally',4,2,'Which sentence uses the “in a lawful way” sense?','She works legally with a valid permit.','They are legally married.','The judge considered the legality of the search.','第一句的 legally 修饰工作行为的合法方式。')]);
P('legend','Legend comes through Old French from Latin legenda, “things to be read”; it can mean an old traditional story, a widely admired person, or the key explaining symbols on a map or chart.',[C('legend.s1','民间故事','The village legend says a bell rings beneath the lake whenever a storm approaches.','村里的传说说，每当暴风雨临近，湖底就会响起钟声。','The village legend says / a bell rings beneath the lake / whenever a storm approaches.','legend.s1 指流传已久、未必有史实依据的故事；says 引出传说内容。','湖底钟声与暴风雨的故事属于民间传说。'),C('legend.s2','体育与人物','After winning six world titles, the runner became a legend admired by young athletes around the country.','赢得六次世界冠军后，这位跑者成为全国年轻运动员敬仰的传奇人物。','After winning six world titles / the runner became a legend / admired by young athletes around the country.','legend 可指长期著名并受人敬仰的人；a legend 作表语。','多次夺冠并广受敬仰，符合传奇人物义。'),C('legend.s3','地图符号','Check the map legend to see whether the dotted line marks a walking trail or a boundary.','查看地图图例，确认点线表示的是步道还是边界。','Check the map legend / to see whether the dotted line marks a walking trail / or a boundary.','legend 可指解释地图或图表符号的图例；whether...or 列出两种解释。','图例说明点线的含义。')],M('The map legend confused readers because it contained only a folk tale and no explanation of the map’s symbols.','The map legend clarified the symbols by explaining what each colour and line represented.','只讲民间故事而不解释地图符号，不是地图图例。','meaning'),[Q('legend',1,1,'A village legend is?','an old traditional story','a legal permit','a pair of leather clothes','legend.s1 指古老传说。'),Q('legend',2,2,'A sports legend is a person who is?','widely admired and famous','unknown and never recognized','a narrow flat rock shelf','legend.s2 指广受敬仰的名人。'),Q('legend',3,3,'A map legend explains?','the symbols and colours on the map','the history of a famous runner','the lease terms for a building','legend.s3 指地图图例。'),Q('legend',4,1,'Which use means a traditional story?','The legend tells of a bell beneath the lake.','She is a legend in athletics.','Read the legend beside the map.','第一句的 legend 指传说故事。')]);
P('legendary','Legendary is formed from legend plus -ary; it means existing in traditional stories or, figuratively, exceptionally famous and admired.',[C('legendary.s1','神话与传说','In the legendary account, a dragon guarded the spring and allowed only honest travellers to drink.','在传说故事中，一条龙守护着泉水，只让诚实的旅人饮用。','In the legendary account / a dragon guarded the spring / and allowed only honest travellers to drink.','legendary.s1 指存在于传说中的；account 是故事叙述。','龙守泉水是故事中的传说情节。'),C('legendary.s2','成就与名声','The goalkeeper made a legendary save in the final, and fans still replay the moment decades later.','这名守门员在决赛中完成了一次传奇般的扑救，几十年后球迷仍会回看那一刻。','The goalkeeper made a legendary save in the final / and fans still replay the moment / decades later.','legendary.s2 表示因成就而极为著名、受人赞赏；save 指守门员扑救。','关键扑救长期被球迷铭记，体现传奇般的引申义。')],M('Fans called the goalkeeper legendary even though no one remembered the save and it had no effect on the match.','Fans called the goalkeeper legendary because the decisive save was celebrated for generations.','若无人记得且毫无影响，称其成就传奇般著名缺乏依据。','context'),[Q('legendary',1,1,'A legendary dragon exists?','in traditional stories','in a legal lease','only on the left-hand side of a map','legendary.s1 指传说中的。'),Q('legendary',2,2,'A legendary save is?','an exceptionally famous or admired save','a save that nobody noticed','a map symbol for a boundary','legendary.s2 表示传奇般著名。'),Q('legendary',3,1,'Why was the goalkeeper’s save legendary?','fans continued to remember and replay it','it was forgotten immediately','the goalkeeper was not in the match','长期被记住说明扑救很有名。'),Q('legendary',4,1,'Legendary is derived from which noun?','legend','legality','leek','legendary 由 legend 派生。')]);
P('legible','Legible derives from Latin legibilis, “able to be read,” from legere “read”; it describes writing or print clear enough to read.',C('legible.s1','表格与手写','Please rewrite the address in dark ink so it remains legible after the form is scanned.','请用深色墨水重写地址，这样表格扫描后仍然清晰可读。','Please rewrite the address in dark ink / so it remains legible / after the form is scanned.','legible 描述字迹或印刷足够清楚、可以辨认；remain 后接形容词。','深色墨水帮助地址在扫描后仍能读清。'),M('The address was legible although every letter had blurred into an unreadable mark.','The address was illegible because the letters had blurred beyond recognition.','无法辨认的字迹应称为 illegible，而不是 legible。','confusable'),[Q('legible',1,1,'Legible writing is?','clear enough to read','too blurred to recognize','written in a language no one knows','legible 指清晰可读。'),Q('legible',2,1,'Why rewrite the address in dark ink?','so it remains readable after scanning','so it becomes a legend','so the form can be left out','深色墨水让扫描后的字迹更清楚。'),Q('legible',3,1,'Which word is the opposite of legible?','illegible','legal','legendary','illegible 是 legible 的反义词。'),Q('legible',4,1,'Legible most often describes?','handwriting or printed text','a political faction','the length of a journey','legible 常形容字迹和印刷文字。')]);
P('legion','Legion comes from Latin legio, “a body of soldiers”; it names an ancient Roman army unit and, figuratively, a very large number.',[C('legion.s1','古罗马军事史','The legion marched north before dawn, carrying supplies for the winter campaign.','这个军团天亮前向北行军，为冬季战役携带补给。','The legion marched north before dawn / carrying supplies / for the winter campaign.','legion.s1 指古罗马军队的大型编制单位；carrying supplies 补充行军准备。','有组织的军队携带补给行军，符合军事义。'),C('legion.s2','数量与群体','A legion of volunteers arrived after the storm to help clear fallen trees from the road.','风暴过后，大批志愿者赶来清除道路上的倒树。','A legion of volunteers arrived after the storm / to help clear fallen trees / from the road.','a legion of 是“大量、一大群”的夸张表达；of 后接人群。','许多志愿者前来帮忙，体现众多义。')],M('A legion of volunteers means exactly one person arrived to clear the road.','A legion of volunteers means a very large group arrived to help.','a legion of 表示大量，不是一个人。','meaning'),[Q('legion',1,1,'In Roman history, a legion was?','a large unit of the army','a political left wing','a university lecture','legion.s1 指罗马军团。'),Q('legion',2,2,'A legion of volunteers means?','a very large number of volunteers','one volunteer only','a group of legal advisers','legion.s2 指大量人群。'),Q('legion',3,1,'What did the Roman legion carry?','supplies for its campaign','leeks for a cooking class','a map legend','例句说军团携带战役补给。'),Q('legion',4,2,'Which phrase uses the figurative number sense?','a legion of fans waited outside','the legion marched under its banner','a legionary joined the army','a legion of fans 表示大批粉丝。')]);
P('legislate','Legislate derives from Latin legal forms built on lex, “law,” and means to make laws or try to control conduct through laws.',[C('legislate.s1','议会与立法','Parliament will legislate on data privacy after a public consultation with researchers and technology firms.','议会将在咨询研究人员和科技公司后，就数据隐私进行立法。','Parliament will legislate on data privacy / after a public consultation / with researchers and technology firms.','legislate on 表示就某议题立法；此处动词不及物，后接介词 on。','议会制定数据隐私相关法律，符合立法义。'),C('legislate.s2','法律规制','The council tried to legislate against unsafe rentals by requiring smoke alarms in every bedroom.','委员会试图通过立法管控不安全出租房，要求每间卧室安装烟雾报警器。','The council tried to legislate against unsafe rentals / by requiring smoke alarms / in every bedroom.','legislate against 表示通过法律禁止或限制某行为；by 引出规制方法。','要求安装报警器是用法律降低出租房风险。')],M('The council legislated against unsafe rentals by removing every safety rule and allowing hazards to remain.','The council legislated against unsafe rentals by requiring smoke alarms and safe exits.','取消安全规则无法体现通过立法管控风险。','meaning'),[Q('legislate',1,1,'To legislate is to?','make laws','read a map legend','lease a building','legislate 指制定法律。'),Q('legislate',2,1,'Parliament will legislate on data privacy. This means it will?','make laws about data privacy','teach a lecture about old maps','make data impossible to read','legislate on 表示就数据隐私立法。'),Q('legislate',3,2,'To legislate against unsafe rentals is to?','use laws to restrict or control them','encourage them by removing all rules','leave all rental homes','legislate against 表示用法律限制。'),Q('legislate',4,1,'Which preposition fits the topic sense?','legislate on privacy','legislate at privacy','legislate under privacy','常说 legislate on a topic。')]);
P('legislation','Legislation derives from Latin legislatio, a law-making action, and means laws considered together or the process of making them.',C('legislation.s1','法规与社会','New legislation requires employers to publish clear pay ranges in every job advertisement.','新法律要求雇主在每则招聘广告中公布明确的薪资范围。','New legislation requires employers / to publish clear pay ranges / in every job advertisement.','legislation 作不可数名词，指法律整体或立法行动；requires 后接宾语加不定式。','新法规为招聘薪酬信息设定要求。'),M('The legislation was a single private opinion with no legal force or connection to any enacted rules.','The legislation was a set of laws passed by the parliament.','没有法律效力的个人意见不是 legislation。','meaning'),[Q('legislation',1,1,'Legislation means?','laws considered as a whole or the act of making them','one person’s private opinion','the group of people who attend a lecture','legislation 指法律整体或立法过程。'),Q('legislation',2,1,'What does the new legislation require employers to do?','publish pay ranges in job advertisements','leave salary details out of every contract','sell leeks at the legislature','新法律要求公布薪资范围。'),Q('legislation',3,1,'Legislation is generally used as?','an uncountable noun','a plural count noun only','an adjective describing a lecture','legislation 通常作不可数名词。'),Q('legislation',4,1,'Which verb commonly collocates with legislation?','pass','wear','leash','议会可 pass legislation（通过立法）。')]);
P('legislative','Legislative is formed from the Latin law-making stem legis- and a related suffix; it describes activities or bodies concerned with making laws.',[C('legislative.s1','立法程序','The committee published a legislative proposal and invited residents to comment before the final vote.','委员会公布了一项立法提案，并邀请居民在最终表决前提出意见。','The committee published a legislative proposal / and invited residents to comment / before the final vote.','legislative.s1 表示与制定法律有关；legislative proposal 是立法提案。','提案进入表决和公众意见程序。'),C('legislative.s2','机构职能','The country’s legislative body meets in the capital and has authority to pass national laws.','该国的立法机构在首都开会，并有权通过全国性法律。','The country’s legislative body meets in the capital / and has authority / to pass national laws.','legislative.s2 表示具有立法权的；修饰 body。','该机构有权制定并通过国家法律。')],M('The legislative body had no authority to make laws and existed only to organize public lectures.','The legislative body had authority to debate and pass laws.','没有立法权、只组织讲座的机构不是 legislative body。','meaning'),[Q('legislative',1,1,'Legislative means related to?','making laws','learning a language','wearing leather','legislative.s1 指与立法有关。'),Q('legislative',2,2,'A legislative body is a group that?','has authority to make laws','only delivers university lectures','leases rooms to lawmakers','legislative.s2 指有立法权的机构。'),Q('legislative',3,1,'What did the committee publish?','a legislative proposal','a leatherback turtle','a map’s legend','它公布了立法提案。'),Q('legislative',4,2,'Which body can pass national laws?','a legislative body','a lecture audience','a group of leavers','有权通过法律的是立法机构。')]);
P('legislature','Legislature is built from the law-making stem legis- with a noun-forming ending; it names the assembly or group authorized to make laws.',C('legislature.s1','政府与预算','The legislature approved the annual budget after debating proposed changes to public transport funding.','立法机构在辩论公共交通经费的拟议调整后，批准了年度预算。','The legislature approved the annual budget / after debating proposed changes / to public transport funding.','legislature 指拥有制定法律权力的机构；approved the budget 是机构采取的正式行动。','议会审议政策和预算属于立法机构职责。'),M('The legislature approved the budget, although it was only a private club with no authority to make laws.','The legislature approved the budget as the country’s law-making assembly.','没有法律制定权的私人俱乐部不是 legislature。','meaning'),[Q('legislature',1,1,'A legislature is?','the group or assembly that makes laws','a single law already passed','a person leaving school','legislature 指立法机构。'),Q('legislature',2,1,'What did the legislature approve?','the annual budget','a leather leash','a legend about a dragon','例句中立法机构批准年度预算。'),Q('legislature',3,1,'Which institution is a legislature?','a parliament with power to pass laws','a lecture hall used by students','a legal office that only advises clients','拥有通过法律权力的议会是 legislature。'),Q('legislature',4,1,'Legislature is related to which activity?','making laws','making leather','leaving a place','立法机构的职责是制定法律。')]);
P('legitimacy','Legitimacy combines legitimate with -acy and means lawful status or, especially in politics, acceptance that authority is rightful.',C('legitimacy.s1','政治与公信力','The new council sought legitimacy by holding a transparent vote and publishing how each district’s ballots were counted.','新委员会通过举行透明投票并公布各区选票的统计方式，争取正当性。','The new council sought legitimacy / by holding a transparent vote / and publishing how each district’s ballots were counted.','legitimacy 指被承认为合法或正当的状态；此处强调公众认可其权威。','透明选举和公开计票有助于形成政治认可。'),M('The council gained legitimacy even though no election was held and no community accepted its authority.','The council gained legitimacy after a transparent election was accepted by the community.','没有选举且无人承认其权威，不支持其获得政治正当性。','context'),[Q('legitimacy',1,1,'Political legitimacy is?','acceptance that authority is rightful','the physical ability to read small print','a short stage of a journey','legitimacy 指被认可的政治正当性。'),Q('legitimacy',2,1,'How did the council seek legitimacy?','by holding a transparent vote and publishing the count','by hiding every ballot','by leaving out all district results','透明投票与公开计票有助争取认可。'),Q('legitimacy',3,1,'How does legitimacy differ from legality?','legitimacy can concern whether authority is accepted as rightful','legitimacy only means the ability to read','legality means family tradition only','legitimacy 涉及权威是否被接受为正当。'),Q('legitimacy',4,1,'Legitimacy is the noun related to?','legitimate','leather','leek','legitimacy 与 legitimate 同词族。')]);
P('legitimate','Legitimate comes from Latin legitimus, “lawful”; it can mean legally permitted, fair and reasonable, historically born within marriage, or make something lawful or acceptable.',[C('legitimate.s1','商业与合规','The charity is a legitimate organization, registered with the state and required to publish annual accounts.','这家慈善机构是合法组织，已在政府登记并须公布年度账目。','The charity is a legitimate organization / registered with the state / and required to publish annual accounts.','legitimate.s1 表示符合法律或正式规则；registered 和 required to publish 说明其正规身份。','登记并履行公开义务支持其合法经营身份。'),C('legitimate.s2','论证与担忧','Residents raised a legitimate concern about the noise because the construction crew worked past midnight.','居民对噪声提出合理担忧，因为施工队工作到午夜之后。','Residents raised a legitimate concern about the noise / because the construction crew / worked past midnight.','legitimate.s2 表示公平合理、可以接受；concern 是有事实依据的担忧。','夜间施工造成噪声，居民担忧有正当理由。'),C('legitimate.s4','制度与认可','The vote helped legitimate the new committee by giving it a clear mandate from residents.','这次投票让新委员会获得居民明确授权，从而使其地位更具正当性。','The vote helped legitimate the new committee / by giving it a clear mandate / from residents.','legitimate 可作及物动词，表示使某事获得合法或社会认可；helped 后接动词原形。','居民投票赋予委员会授权。','')],M('The residents had no reasonable basis to complain about the midnight noise, yet the article called their concern legitimate.','The residents had a legitimate concern because construction continued past midnight.','持续到午夜的噪声为居民担忧提供了合理依据；若没有依据则不应称 legitimate。','context'),[Q('legitimate',1,1,'A legitimate business is?','lawful under the rules','impossible to read','a legendary story only','legitimate.s1 指合法经营。'),Q('legitimate',2,2,'A legitimate concern is?','reasonable and supported by good grounds','unfair and invented without evidence','a Roman military unit','legitimate.s2 表示合理正当。'),Q('legitimate',3,4,'To legitimate a committee is to?','give it lawful or accepted status','make its reports illegible','leave it out of the vote','legitimate.s4 作动词表示使正当或获认可。'),Q('legitimate',4,3,'In older legal language, a legitimate child was?','born to parents married to each other','born with a legal profession','a child who drafted legislation','legitimate.s3 是旧法律用语，指出生时父母有婚姻关系。')]);
P('legitimately','Legitimately is formed from legitimate plus -ly and means lawfully, fairly, or with sound justification.',C('legitimately.s1','权利与申诉','The tenant can legitimately ask for a repair because the leak has damaged the ceiling and the lease assigns repairs to the landlord.','由于漏水损坏了天花板且租约规定由房东负责维修，租户有充分理由要求修理。','The tenant can legitimately ask for a repair / because the leak has damaged the ceiling / and the lease assigns repairs to the landlord.','legitimately 表示有正当理由地；because 从句给出合理依据。','租约责任和实际损坏支持维修请求。'),M('The tenant legitimately demanded repairs even though the ceiling was undamaged and the lease assigned all upkeep to the tenant.','The tenant legitimately demanded repairs after the leak damaged the ceiling under the landlord’s responsibility.','没有损坏且责任不属于房东时，这项要求缺乏正当依据。','context'),[Q('legitimately',1,1,'To ask legitimately is to ask?','lawfully or with good reason','without any possible justification','only in a legendary story','legitimately 表示合法或有充分理由地。'),Q('legitimately',2,1,'Why could the tenant legitimately request repairs?','the leak damaged the ceiling and the lease assigned repairs to the landlord','the ceiling was undamaged','the tenant had no lease','损坏和合同条款构成正当理由。'),Q('legitimately',3,1,'Legitimately is the adverb related to?','legitimate','legislature','legume','legitimately 由 legitimate 加 -ly 派生。'),Q('legitimately',4,1,'Which phrase best fits?','legitimately claim a refund for a defective item','legitimately ignore every contract term','legitimately leave the law unread','有缺陷商品的退款请求有充分理由。')]);
P('legitimism','Legitimism comes from French légitimisme and names a political principle that supports a hereditary ruler as the rightful lawful monarch.',C('legitimism.s1','欧洲政治史','In the nineteenth-century debate, legitimism held that hereditary succession made a monarch the rightful ruler.','在十九世纪的争论中，正统主义认为世袭继承使君主成为正当统治者。','In the nineteenth-century debate / legitimism held / that hereditary succession made a monarch the rightful ruler.','legitimism 指支持世袭君主拥有正统统治权的政治原则；held that 引出其主张。','世袭继承被视为王位合法性的来源。'),M('The historian called the republican movement legitimism even though it rejected hereditary monarchy and supported elected government.','The historian called support for the hereditary monarch legitimism.','反对世袭君主制的共和运动不符合 legitimism 的核心主张。','meaning'),[Q('legitimism',1,1,'Legitimism supports?','a hereditary monarch regarded as the rightful ruler','a legislature chosen by random lottery','a policy of leaving laws out','legitimism 主张世袭君主的正统权利。'),Q('legitimism',2,1,'Which debate might involve legitimism?','who has the lawful hereditary claim to a throne','whether a map legend is readable','how many legs a table needs','王位世袭权争论可能涉及正统主义。'),Q('legitimism',3,1,'Legitimism is a political?','principle or doctrine','kind of leather','unit of distance','legitimism 是政治原则。'),Q('legitimism',4,1,'A legitimist would most likely defend?','a hereditary ruler’s claim to the throne','abolishing every monarchy in favor of elections','a school leaver’s travel plans','正统主义者会支持世袭君主的王位主张。')]);
P('legitimize','Legitimize combines legitimate with -ize and means to make something lawful or to make it appear socially or politically acceptable.',C('legitimize.s1','权力与认可','The referendum was designed to legitimize the new council by showing that residents supported its authority.','这次公投旨在通过显示居民支持其权威，使新委员会获得正当性。','The referendum was designed to legitimize the new council / by showing / that residents supported its authority.','legitimize 作及物动词，指使某事获得法律或社会认可；by showing 说明方式。','通过居民投票表达支持能增强委员会的认可度。'),M('The report said the referendum would legitimize the council, although the vote was cancelled and no residents participated.','The report said the referendum could legitimize the council if residents voted to support it.','公投取消且无人投票，无法借此获得公众认可。','meaning'),[Q('legitimize',1,1,'To legitimize a decision is to?','make it lawful or accepted as proper','make it harder to read','turn it into a Roman legion','legitimize 指使某事合法或获得认可。'),Q('legitimize',2,1,'How could the referendum legitimize the council?','by showing residents supported its authority','by cancelling the vote','by hiding the results from residents','投票支持可增强其正当性。'),Q('legitimize',3,1,'Legitimize is formed from legitimate plus?','-ize','-less','-er','legitimate 加 -ize 构成 legitimize。','word-formation'),Q('legitimize',4,1,'Which distinction is correct?','legalize makes lawful; legitimize can also make socially acceptable','legitimize always means to make unreadable','legalize means to leave a room','legitimize 也可表示使社会上可接受。')]);
P('legume','Legume comes from Latin legumen, “bean or pulse,” and names a plant of the pea family or its edible pod and seeds.',C('legume.s1','饮食与农业','The farm rotates legumes with cereal crops because many beans and peas help replenish nitrogen in the soil.','农场把豆科作物与谷物轮作，因为许多豆类有助于补充土壤中的氮。','The farm rotates legumes with cereal crops / because many beans and peas / help replenish nitrogen in the soil.','legume 指豆科植物及其荚果；because 引出轮作的土壤作用。','豆类作物根部可与固氮细菌共生，帮助土壤恢复氮素。'),M('The nutrition guide called lentils a legume, but claimed they were a type of fish with no relation to plants.','The nutrition guide called lentils a legume, a plant of the pea family and its edible seeds.','扁豆属于豆科植物，不是鱼类。','meaning'),[Q('legume',1,1,'A legume is a plant related to?','peas, beans, or lentils','leeks and lemons only','leopards and turtles','legume 指豌豆、菜豆等豆科植物。'),Q('legume',2,1,'Why did the farm rotate legumes with cereal crops?','they can help replenish nitrogen in soil','they consume all soil nutrients permanently','they are a kind of leather','豆科植物可帮助补充土壤氮素。'),Q('legume',3,1,'Which food is a legume?','lentils','lemon juice','lettuce leaves only','小扁豆属于豆类。'),Q('legume',4,1,'Legume can refer to?','a pea-family plant or its edible pods and seeds','a law-making assembly','a narrow rock shelf','legume 可指植物及其荚和种子。')]);
P('leisure','Leisure derives through Old French from Latin licere, “to be permitted”; it means free time away from work or, attributively, activities done for enjoyment.',[C('leisure.s1','工作与休息','After the harvest, the workers finally had a week of leisure to visit relatives and sleep without an alarm.','收割结束后，工人们终于有一周闲暇，可以探亲并不用闹钟叫醒。','After the harvest / the workers finally had a week of leisure / to visit relatives and sleep without an alarm.','leisure.s1 指工作或职责之外的自由时间；a week of leisure 是一周闲暇。','他们暂时没有工作任务，可以休息或探亲。'),C('leisure.s2','休闲活动','The town invested in leisure facilities, including a swimming pool, walking paths, and a community art room.','小镇投资建设休闲设施，包括游泳池、步道和社区艺术室。','The town invested in leisure facilities / including a swimming pool, walking paths, / and a community art room.','leisure 可作定语，表示供人们娱乐放松的；facilities 列举具体活动设施。','游泳、散步和艺术活动都属于休闲。')],M('She had no leisure at all because she was working every hour of the day, yet the diary described the week as free time.','She had a week of leisure because she was not working and could choose how to spend her time.','全天工作、没有自由时间与 leisure 的定义相反。','meaning'),[Q('leisure',1,1,'Leisure is?','time free from work or duty','a legal contract for a flat','a leg of a journey','leisure 指闲暇时间。'),Q('leisure',2,2,'Leisure facilities are designed for?','activities people do for enjoyment','official law-making only','storing leftover food','leisure facilities 用于休闲活动。'),Q('leisure',3,1,'What could the workers do during their week of leisure?','visit relatives and rest','work every hour without a break','draft new legislation','闲暇时间可以休息或探亲。'),Q('leisure',4,2,'Which phrase uses leisure attributively?','leisure activities in the town','a week of leisure','leisure is rare during harvest','leisure activities 表示休闲活动。')]);
P('leisurely','Leisurely is formed from leisure plus -ly and describes a relaxed, unhurried pace; it can function as an adjective or adverb.',C('leisurely.s1','出行与节奏','They took a leisurely walk along the canal, stopping to watch boats pass beneath the old bridge.','他们沿运河悠闲散步，还停下来观看小船从旧桥下经过。','They took a leisurely walk along the canal / stopping to watch boats pass / beneath the old bridge.','leisurely 作形容词修饰 walk，表示不慌不忙；stopping 补充散步时的活动。','沿途停下观景说明步行节奏轻松从容。'),M('The hikers took a leisurely walk by sprinting at full speed and refusing to stop for even a moment.','The hikers took a leisurely walk at a relaxed pace and paused to enjoy the view.','全速冲刺且不停步与悠闲、从容的节奏相反。','meaning'),[Q('leisurely',1,1,'A leisurely walk is?','relaxed and unhurried','a race at maximum speed','a legal hearing','leisurely 表示悠闲从容。'),Q('leisurely',2,1,'What did the walkers stop to watch?','boats passing beneath a bridge','a legislature voting on a bill','a leopard hunting a lemon','例句中他们观看小船经过。'),Q('leisurely',3,1,'Which phrase is grammatically correct?','a leisurely breakfast','a leisurelier breakfastly','a leisure breakfasting','leisurely 可作形容词修饰 breakfast。'),Q('leisurely',4,1,'Leisurely is related to which noun?','leisure','leek','legality','leisurely 由 leisure 派生。','word-formation')]);
P('lemon','Lemon comes through French and Arabic from Persian līmūn; it names the sour yellow fruit and tree, and informally a faulty or disappointing product.',[C('lemon.s1','饮食与水果','She squeezed a slice of lemon into the tea to balance its sweetness with a sharp citrus taste.','她把一片柠檬挤进茶里，用清爽的柑橘酸味平衡甜味。','She squeezed a slice of lemon into the tea / to balance its sweetness / with a sharp citrus taste.','lemon.s1 指黄色酸味水果；a slice of lemon 是常见搭配。','柠檬汁带有酸味，可平衡饮料甜度。'),C('lemon.s2','植物与种植','A lemon tree grew in a sheltered corner of the courtyard where it received plenty of winter sun.','庭院背风处长着一棵柠檬树，冬天也能晒到充足阳光。','A lemon tree grew in a sheltered corner of the courtyard / where it received / plenty of winter sun.','lemon 可指结柠檬果的树；lemon tree 是树木义。','庭院中生长的是柠檬树，而不是水果本身。'),C('lemon.s3','口语评价商品','The used car turned out to be a lemon, breaking down repeatedly during the first month.','那辆二手车结果是个蹩脚货，第一个月就反复抛锚。','The used car turned out to be a lemon / breaking down repeatedly / during the first month.','lemon 可口语指有缺陷、令人失望的产品；turn out to be 表示结果是。','新买的车多次故障，符合蹩脚货的引申义。')],M('The used car was a lemon, meaning it ran perfectly and never needed repair during years of use.','The used car was a lemon because it repeatedly broke down and required repairs.','多年运行良好、从不维修不是口语所谓的 lemon。','meaning'),[Q('lemon',1,1,'A lemon is a yellow sour?','fruit','large sea turtle','type of furniture support','lemon.s1 指柠檬水果。'),Q('lemon',2,2,'A lemon tree is?','a tree that produces lemons','a faulty car','a long journey stage','lemon.s2 指柠檬树。'),Q('lemon',3,3,'A used car called a lemon is?','faulty or disappointing','especially reliable and trouble-free','a sour fruit installed in a car','lemon.s3 口语指有毛病的产品。'),Q('lemon',4,3,'Why was the used car a lemon?','it broke down repeatedly','it was a tree in a courtyard','it made the tea less sweet','反复抛锚说明车辆有缺陷。')]);
P('lend','Lend comes from Old English lænan, “grant temporarily”; it means give something for a time expecting its return, loan money, or add a quality or support to something.',[C('lend.s1','物品借用','Could you lend me your umbrella until the rain stops? I will bring it back this afternoon.','雨停前能把伞借给我吗？我今天下午就还给你。','Could you lend me your umbrella / until the rain stops? / I will bring it back this afternoon.','lend me something 表示把物品借出给我暂用；bring it back 说明之后归还。','借伞是暂时交付并预期归还。'),C('lend.s2','金融与贷款','The bank agreed to lend the small firm money after reviewing its accounts and repayment plan.','银行审查这家小公司的账目和还款计划后，同意向其贷款。','The bank agreed to lend the small firm money / after reviewing its accounts / and repayment plan.','lend money 指放贷，通常要求借款方偿还；lend someone money 是常见结构。','银行给企业资金并有还款安排。'),C('lend.s3','增添特质','A narrow skylight lends the kitchen a feeling of openness even on cloudy days.','即使阴天，一扇狭长天窗也让厨房显得更加开阔。','A narrow skylight lends the kitchen a feeling of openness / even on cloudy days.','lend 可表示给某物增添某种特质；lend something a quality 是抽象搭配。','天窗使厨房呈现开阔感。')],M('The bank lent the firm money with the clear agreement that the firm would never repay it.','The bank lent the firm money under an agreement requiring repayment.','lend 的贷款义通常包含偿还预期。','meaning'),[Q('lend',1,1,'To lend someone an umbrella is to?','let them use it temporarily and expect it back','give it away permanently','rent a lecture hall to them','lend.s1 指暂借物品。'),Q('lend',2,2,'Banks lend money to firms when they?','provide funds that must be repaid','give funds with no expectation of return','borrow money from the firms','lend.s2 指放贷，通常需要偿还。'),Q('lend',3,3,'A skylight lends a kitchen openness means it?','gives the room a more open feeling','borrows a window from the kitchen','leases the kitchen for a year','lend.s3 可表示赋予某种特质。'),Q('lend',4,1,'What is the past tense of lend?','lent','lended','leant','lend 的过去式和过去分词是 lent。','verb-form')]);
P('lender','Lender is formed from lend plus -er and names a person or organization that provides money or property temporarily, especially a bank.',C('lender.s1','银行与贷款','The lender checked the applicant’s income before approving the mortgage for the apartment.','贷款方在批准这套公寓的按揭贷款前核查了申请人的收入。','The lender checked the applicant’s income / before approving the mortgage / for the apartment.','lender 指出借资金的个人或机构；mortgage lender 是按揭贷款方。','核查收入并批准贷款是银行出借资金的职责。'),M('The lender paid interest to the borrower for receiving money, rather than providing a loan.','The lender provided the loan and charged the borrower interest.','收取利息并提供资金的是 lender；借款方是 borrower。','meaning'),[Q('lender',1,1,'A lender is the person or organization that?','provides money that is expected to be repaid','receives a loan and repays it','teaches a lecture on law','lender 指出借或贷款的一方。'),Q('lender',2,1,'What did the lender check?','the applicant’s income','the length of the lecturer’s speech','the color of a lemon','贷款方审查了申请人的收入。'),Q('lender',3,1,'Who is the opposite party to a lender?','a borrower','a lessor','a lecturer','borrower 是借款人，与 lender 相对。'),Q('lender',4,1,'Lender is formed from lend plus?','-er','-ment','-ous','-er 表示出借者。','word-formation')]);
P('lending','Lending is formed from lend plus -ing and names the activity of temporarily giving money or goods to another person.',C('lending.s1','金融与信贷','Lending to small businesses slowed when interest rates rose, even though demand for new equipment remained high.','利率上升后，对小企业的放贷放缓，尽管它们对新设备的需求仍然很高。','Lending to small businesses slowed / when interest rates rose / even though demand for new equipment remained high.','lending 作不可数名词指放贷活动；to small businesses 标明贷款对象。','利率上升使银行放贷速度放缓。'),M('The bank reduced its lending by giving twice as many new loans as before.','The bank reduced its lending by approving fewer new loans.','贷款数量增加表示 lending 上升，不是减少。','meaning'),[Q('lending',1,1,'Lending is the activity of?','providing money or goods temporarily','collecting unused food','making a political legend','lending 指借出或放贷活动。'),Q('lending',2,1,'What happened to lending to small businesses?','it slowed after interest rates rose','it doubled after all rates disappeared','it became a type of leisure activity','利率上涨后小企业贷款放缓。'),Q('lending',3,1,'Lending is usually used as?','an uncountable noun','a plural noun for borrowers','an adjective meaning long','lending 通常作不可数名词。'),Q('lending',4,1,'Which phrase is natural?','bank lending to local firms','a lending of one lecturer','lending the law on a wall','bank lending to local firms 是自然搭配。')]);
P('length','Length derives from Old English lengthu, related to long; it measures how far something extends from end to end or how long an event lasts.',C('length.s1','测量与尺寸','The carpenter measured the length of the shelf before cutting a matching piece of wood.','木匠在切割配套木板前测量了搁板的长度。','The carpenter measured the length of the shelf / before cutting / a matching piece of wood.','length 指物体从一端到另一端的尺寸；the length of 是常见结构。','测量搁板两端之间的距离以裁切合适木板。'),M('The length of the shelf was its weight in kilograms rather than the distance from one end to the other.','The length of the shelf was the distance from one end to the other.','length 指长短或距离，不是重量。','measurement'),[Q('length',1,1,'The length of a shelf measures?','the distance from one end to the other','its weight','the number of legal documents it holds','length 指物体两端之间的距离。'),Q('length',2,1,'Why did the carpenter measure the shelf’s length?','to cut a matching piece of wood','to decide whether to lend a lemon','to identify a political party','测量长度有助于裁切合适木板。'),Q('length',3,1,'Which phrase uses length correctly?','The rope is ten metres in length.','The rope is ten metres in leeway.','The rope is ten metres in lecturer.','in length 是正确搭配。'),Q('length',4,1,'Length is most directly related to?','how long something is','how heavy it is','how legal it is','length 描述长短。')]);
P('lengthen','Lengthen is formed from length plus the verb-forming suffix -en and means make something longer or become longer.',[C('lengthen.s1','施工与尺寸','The tailor lengthened the coat sleeves by adding matching fabric at each cuff.','裁缝在每个袖口接上相配的布料，把大衣袖子加长了。','The tailor lengthened the coat sleeves / by adding matching fabric / at each cuff.','lengthen 作及物动词表示使某物变长；by 引出加长方法。','在袖口添加布料使袖长增加。'),C('lengthen.s1','自然变化','The shadows lengthened across the field as the sun moved lower in the evening sky.','傍晚太阳渐渐西沉，田野上的影子也越来越长。','The shadows lengthened across the field / as the sun moved lower / in the evening sky.','lengthen 也可作不及物动词，表示自身变长；as 引出变化原因或同时发生的过程。','太阳高度降低时，影子逐渐变长。')],M('The tailor lengthened the sleeves by cutting several inches off each cuff.','The tailor lengthened the sleeves by adding fabric at each cuff.','剪掉袖口布料会使袖子缩短，不会加长。','meaning'),[Q('lengthen',1,1,'To lengthen a sleeve is to?','make it longer','make it shorter','make it less legible','lengthen 意为加长。'),Q('lengthen',2,1,'How did the tailor lengthen the sleeves?','by adding matching fabric','by cutting fabric away','by leaving the sleeves out','裁缝通过接布料加长袖子。'),Q('lengthen',3,1,'When did the shadows lengthen?','as the sun moved lower','when the sun rose directly overhead','when the field was shortened','傍晚太阳降低时影子变长。'),Q('lengthen',4,1,'Lengthen is formed from length plus?','-en','-ly','-ship','length 加 -en 构成动词 lengthen。','word-formation')]);
P('lengthwise','Lengthwise combines length with -wise and means along the longest dimension rather than across the width.',C('lengthwise.s1','烹饪与切割','Cut the zucchini lengthwise into long strips before brushing them with oil.','先把西葫芦纵向切成长条，再刷上油。','Cut the zucchini lengthwise / into long strips / before brushing them with oil.','lengthwise 作副词，指沿物体较长方向切；into long strips 说明切出的形状。','切出的长条与蔬菜长轴平行。'),M('The cook sliced the zucchini lengthwise by cutting it into short rounds across its width.','The cook sliced the zucchini crosswise into short rounds.','横向切成短圆片应称 crosswise，不是 lengthwise。','distinction'),[Q('lengthwise',1,1,'To cut a vegetable lengthwise is to cut?','along its longest direction','across its shortest width','into a legal contract','lengthwise 指沿长轴方向。'),Q('lengthwise',2,1,'What shape did the zucchini become?','long strips','short round slices','a leather bag','纵向切成了长条。'),Q('lengthwise',3,1,'Which word can also mean lengthwise?','lengthways','legally','leisurely','lengthways 与 lengthwise 意义接近。'),Q('lengthwise',4,1,'Lengthwise is the opposite direction of?','crosswise','lengthen','left-hand side','crosswise 指横向，与 lengthwise 相对。')]);
P('lengthy','Lengthy is formed from length plus -y and describes something that takes a long time, often with a suggestion that it is too long.',C('lengthy.s1','会议与时间','The committee issued a lengthy report that took three months to prepare and required several rounds of review.','委员会发布了一份冗长的报告，准备工作花了三个月，还经过多轮审阅。','The committee issued a lengthy report / that took three months to prepare / and required several rounds of review.','lengthy 修饰 report，表示篇幅或耗时很长，常带有过长的暗示。','报告准备时间久并经过多轮审查，符合冗长义。'),M('The lengthy hearing finished in two minutes and included only a single short question.','The lengthy hearing lasted several hours and included many detailed questions.','两分钟且只有一个短问题的听证会不算冗长。','meaning'),[Q('lengthy',1,1,'A lengthy meeting is?','long and taking a considerable amount of time','brief and over almost immediately','held only during leisure time','lengthy 表示耗时很长。'),Q('lengthy',2,1,'How long did the report take to prepare?','three months','two minutes','one afternoon with no review','报告准备了三个月。'),Q('lengthy',3,1,'Lengthy can suggest that something is?','perhaps longer than necessary','impossible to measure','legally forbidden','lengthy 常带有“冗长”的意味。'),Q('lengthy',4,1,'Lengthy is derived from?','length','leash','leek','length 加 -y 构成 lengthy。','word-formation')]);
P('lenient','Lenient comes through French from Latin lenire, “soften”; it describes a punishment or judge that is not as severe as expected, or a person who is not strict.',[C('lenient.s1','司法与处罚','The judge was lenient and ordered community service instead of the maximum prison sentence.','法官从轻处罚，没有判最高刑期，而是判了社区服务。','The judge was lenient / and ordered community service / instead of the maximum prison sentence.','lenient.s1 描述处罚不严厉或从轻；instead of 对照实际处罚与最高刑期。','判社区服务而非最高刑期体现宽大。',''),C('lenient.s2','教育与规则','Ms. Patel is lenient with late homework when students explain a genuine family emergency.','学生说明确有家庭紧急情况时，帕特尔老师会宽容对待迟交的作业。','Ms. Patel is lenient with late homework / when students explain / a genuine family emergency.','lenient with someone or something 表示对其宽容；when 引出允许迟交的条件。','老师在特殊情况下不严格执行迟交处罚。')],M('The lenient judge imposed the most severe sentence available and refused to consider any circumstances.','The lenient judge imposed a reduced sentence after considering the circumstances.','施加最严厉处罚且不考虑情况不属于宽大处理。','meaning'),[Q('lenient',1,1,'A lenient sentence is?','less severe than expected','the longest sentence possible','a sentence that cannot be read','lenient.s1 指较轻的处罚。'),Q('lenient',2,2,'A teacher who is lenient with late work?','may allow some flexibility','always gives the maximum punishment','leaves every student out of class','lenient.s2 指不苛刻、宽容。'),Q('lenient',3,1,'Why was the judge lenient?','the sentence was reduced after considering the case','the judge gave the maximum prison term','the judge refused to hear evidence','从轻处罚体现宽大。'),Q('lenient',4,1,'Lenient is closest in meaning to?','merciful','lengthy','leathery','merciful 与 lenient 都可指宽大仁慈。')]);
P('lenitive','Lenitive comes from Latin lenire, “to soften”; as an adjective it means soothing or easing pain, and as a noun it can name a soothing remedy.',[C('lenitive.s1','语气与沟通','Her lenitive reply acknowledged the complaint while avoiding the harsh rebuke the manager had expected.','她的答复语气缓和，回应了投诉，却没有像经理预想的那样严厉斥责。','Her lenitive reply acknowledged the complaint / while avoiding the harsh rebuke / the manager had expected.','lenitive.s1 作形容词，表示缓和严厉语气；while 引出对照。','答复平和且没有责备，体现缓和义。',''),C('lenitive.s2','药物与缓解','The physician recommended a mild lenitive to soothe the irritated throat while the infection ran its course.','医生建议用温和的缓和剂舒缓受刺激的喉咙，同时等待感染自行好转。','The physician recommended a mild lenitive / to soothe the irritated throat / while the infection ran its course.','lenitive.s2 作名词指能缓和疼痛或刺激的药剂；to soothe 说明用途。','药剂舒缓症状但不直接消除感染。')],M('The physician called the harsh abrasive treatment a lenitive because it intensified pain and irritation.','The physician called the soothing treatment a lenitive because it eased irritation.','加重疼痛和刺激的疗法不是缓和剂。','meaning'),[Q('lenitive',1,1,'A lenitive reply is?','soothing and not harsh','a long legal lecture','a very severe reprimand','lenitive.s1 指缓和、舒缓的。'),Q('lenitive',2,2,'A lenitive can be a medicine that?','eases pain or irritation','causes more irritation','lengthens a person’s leg','lenitive.s2 可指缓和剂。'),Q('lenitive',3,1,'What did the doctor hope the remedy would do?','soothe the irritated throat','make the infection more painful','make the illness impossible to read','缓和剂用于舒缓喉咙刺激。'),Q('lenitive',4,1,'Lenitive is related to lenient through the idea of?','softening or easing','measuring length','leaving a place','二者词源相关，都含缓和之意。')]);
P('lens','Lens comes from Latin lens, “lentil,” because an early optical lens resembled the seed; it can mean a light-bending glass, a camera or eye part, or a figurative viewpoint.',[C('lens.s1','光学与显微镜','The microscope’s convex lens bends light to enlarge the image of the tiny cell.','显微镜的凸透镜使光线弯折，从而放大微小细胞的图像。','The microscope’s convex lens bends light / to enlarge the image / of the tiny cell.','lens.s1 指使光线弯折的透镜；to enlarge 说明光学作用。','凸透镜折射光线以放大样本。'),C('lens.s2','摄影与视觉','Dust on the camera lens appeared as a dark spot in every photograph.','相机镜头上的灰尘在每张照片中都显成一个黑点。','Dust on the camera lens appeared / as a dark spot / in every photograph.','lens 可指相机镜头或眼睛晶状体；camera lens 是摄影义。','镜头上的灰尘会影响成像。'),C('lens.s3','分析视角','The historian examined the migration through the lens of family letters rather than government statistics.','历史学家通过家庭书信而非政府统计数据的视角来研究迁徙。','The historian examined the migration / through the lens of family letters / rather than government statistics.','through the lens of 是比喻表达，指看待问题的视角。','书信提供一种分析迁徙的观察角度。')],M('The photographer cleaned the camera lens, which is the paper label explaining map symbols.','The photographer cleaned the camera lens, the glass part that focuses light.','相机镜头是聚焦光线的光学部件，不是地图图例。','confusable'),[Q('lens',1,1,'An optical lens bends?','light','sound into words','a legal sentence','lens.s1 指能折射光线的透镜。'),Q('lens',2,2,'Dust on a camera lens may affect?','the photographs it takes','the legal status of a lease','the length of a lecture','镜头灰尘会影响照片成像。'),Q('lens',3,3,'“Through the lens of history” means?','from the viewpoint of historical analysis','through a physical camera only','on the left-hand side of the page','lens.s3 比喻观察或分析角度。'),Q('lens',4,1,'Why was the optical part called a lens in Latin?','it resembled a lentil seed','it was made from a leather leash','it was invented by a legislature','词源解释其形状类似扁豆。')]);
P('leopard','Leopard came through Old French from Latin leopardus; the name was historically associated with lion-like and panther-like animals, and it can also appear in a proverb about an unchanging nature.',[C('leopard.s1','野生动物','A leopard moved silently through the branches, its spotted coat blending into the dappled light.','一只花豹在树枝间悄然移动，带斑点的皮毛融入斑驳的光线。','A leopard moved silently through the branches / its spotted coat blending / into the dappled light.','leopard.s1 指生活在非洲和亚洲的大型斑点猫科动物；its 指花豹的皮毛。','斑点皮毛和树上活动是花豹的特征。'),C('leopard.s2','习语与性格','The coach joked that a leopard cannot change its spots after the player repeated the same risky move.','球员再次做出同样冒险的动作后，教练开玩笑说“江山易改，本性难移”。','The coach joked / that a leopard cannot change its spots / after the player repeated the same risky move.','a leopard cannot change its spots 是谚语，比喻人的本性难以改变。','球员重复旧习惯，引出谚语的比喻用法。')],M('The zoologist identified the spotted leopard as a small flightless bird native to New Zealand.','The zoologist identified the spotted leopard as a large wild cat native to Africa and Asia.','leopard 是大型猫科动物，不是新西兰不会飞的鸟。','meaning'),[Q('leopard',1,1,'A leopard is a large wild?','cat with a spotted coat','bird with a long bill','turtle with a ridged shell','leopard.s1 指花豹。'),Q('leopard',2,2,'“A leopard cannot change its spots” means?','a person’s nature is difficult to change','a leopard can change its coat colour at will','a map legend is unreadable','leopard.s2 是“本性难移”的谚语。'),Q('leopard',3,1,'Where did the leopard move in the example?','through the branches','under the lecture-room desk','along the legislature’s aisle','例句中花豹在树枝间移动。'),Q('leopard',4,2,'Which phrase uses leopard figuratively?','a leopard cannot change its spots','a spotted leopard in a tree','a leopard’s habitat','谚语用豹比喻难以改变的性格。')]);
P('leprosy','Leprosy comes from Greek lepra through Latin and French, ultimately from lepros, “scaly”; modern medicine also calls it Hansen’s disease.',C('leprosy.s1','医学与公共健康','Leprosy can affect skin and peripheral nerves, but early diagnosis and multidrug treatment can cure the infection.','麻风病会影响皮肤和周围神经，但早期诊断并采用多药联合治疗可以治愈感染。','Leprosy can affect skin and peripheral nerves / but early diagnosis and multidrug treatment / can cure the infection.','leprosy 是由细菌引起、可能影响皮肤和周围神经的慢性传染病；but 强调可治疗。','及时使用联合抗生素可以治愈疾病，避免宿命化污名。'),M('The clinic called it leprosy even though tests showed no infection and the patient had no skin or nerve symptoms.','The clinic diagnosed leprosy after tests confirmed the infection affecting the patient’s skin and nerves.','没有感染证据和相关症状时不能仅凭称呼断定为麻风病。','meaning'),[Q('leprosy',1,1,'Leprosy is also known as?','Hansen’s disease','legion disease','leatherback syndrome','leprosy 的现代医学名称也称 Hansen’s disease。'),Q('leprosy',2,1,'Which parts can leprosy affect?','skin and peripheral nerves','only the lens of the eye','the legs of a table','麻风病可影响皮肤和周围神经。'),Q('leprosy',3,1,'Can leprosy be treated?','yes, with multidrug antibiotic treatment','no, it is always incurable','only by a legislative vote','麻风病可通过联合抗生素治疗。'),Q('leprosy',4,1,'Why is “Hansen’s disease” used in modern medical language?','it names the condition without using an old stigmatizing label','it refers to a different kind of legume','it describes a legal contract','Hansen’s disease 是较中性的现代医学名称。')]);
P('lesbian','Lesbian is associated with Lesbos, the Greek island of the poet Sappho; it is a noun for a woman attracted to women or an adjective relating to such women.',[C('lesbian.s1','身份与表达','Nora came out as a lesbian to her close friends after choosing a time when she felt safe and supported.','诺拉在觉得安全且有人支持时，向亲密朋友公开了自己是女同性恋者。','Nora came out as a lesbian / to her close friends / after choosing a time when she felt safe and supported.','lesbian.s1 作名词指在情感或性方面被女性吸引的女性；come out as 是公开身份的表达。','她向信任的朋友表达自己的身份。'),C('lesbian.s2','权益与社会','The university hosted a panel on lesbian representation in contemporary film and television.','大学举办了一场关于当代影视中女同性恋者形象呈现的讨论会。','The university hosted a panel / on lesbian representation / in contemporary film and television.','lesbian.s2 作形容词，修饰 representation，表示与女同性恋者相关。','讨论主题是影视作品中的相关群体形象。')],M('The article used lesbian as an insult for a woman based only on her clothing, without describing her identity or relationships.','The article used lesbian neutrally for a woman who identifies as attracted to women.','该身份词应描述本人身份或情感取向，不应仅凭衣着推断或当作侮辱。','register'),[Q('lesbian',1,1,'As a noun, lesbian refers to?','a woman attracted to women','any person who teaches at a university','a person who rents an apartment','lesbian.s1 指女同性恋者。'),Q('lesbian',2,2,'In “lesbian representation in film,” lesbian is?','an adjective relating to women attracted to women','a noun for a legal contract','a verb meaning to leave a place','此处 lesbian 修饰 representation。'),Q('lesbian',3,1,'What did Nora do when she came out?','shared her identity with close friends','signed a lease for a film studio','gave a lecture on a lemon','come out 表示公开自己的身份。'),Q('lesbian',4,2,'A panel on lesbian representation would discuss?','how lesbian characters are portrayed in media','the length of a window ledge','how to lend money legally','主题是影视中相关群体的呈现。')]);
P('less','Less is the comparative form of little; it can mark a smaller amount, a lower degree, or subtraction from a number.',[C('less.s1','数量与比较','This recipe uses less sugar than the original because the fruit is already very sweet.','这个食谱用的糖比原版少，因为水果本身已经很甜。','This recipe uses less sugar than the original / because the fruit is already very sweet.','less.s1 用于表示较少的数量，通常修饰不可数名词 sugar；than 引出比较对象。','配方减少糖量以适应水果甜度。'),C('less.s2','程度与评价','The second proposal is less risky, although it will take a little longer to complete.','第二个方案风险较小，不过完成它会多花一点时间。','The second proposal is less risky / although it will take a little longer / to complete.','less 可作副词表示程度较低，修饰形容词 risky。','第二个方案的风险程度更低。'),C('less.s3','减法与扣除','The invoice lists the total as one hundred dollars less the delivery fee.','发票列出的总额是一百美元，扣除配送费。','The invoice lists the total / as one hundred dollars less the delivery fee.','less 可用于正式书写中表示减去或扣除；此处 less 引出减项。','配送费从总额中扣除。')],M('The fruit was already sweet, so the recipe used less sugar by adding an extra cup of sugar.','The fruit was already sweet, so the recipe used less sugar by reducing the added amount.','额外多加一杯糖会增加糖量，不会减少糖量。','meaning'),[Q('less',1,1,'Less sugar means?','a smaller amount of sugar','a greater amount of sugar','sugar that is impossible to measure','less.s1 指较少数量。'),Q('less',2,2,'A less risky plan is?','lower in risk','more dangerous','the shortest leg of a journey','less.s2 表示程度较低。'),Q('less',3,3,'“One hundred dollars less the fee” means?','subtract the fee from one hundred dollars','add the fee to one hundred dollars','leave the price unreadable','less.s3 表示扣除。'),Q('less',4,1,'Less is the comparative form of?','little','leisure','legal','little 的比较级是 less。')]);
P('less than','Less than combines less with than and means an amount, number, or degree below a stated comparison or limit.',C('less than.s1','金额与数量','The repair took less than two hours because the technician had already identified the damaged cable.','维修不到两小时就完成了，因为技术员已经找到了损坏的电缆。','The repair took less than two hours / because the technician had already identified / the damaged cable.','less than 后接数值，表示少于、不足；此处修饰时间长度。','维修时间低于两小时。'),M('The repair took less than two hours, meaning it lasted longer than three full hours.','The repair took less than two hours, meaning it finished before two hours had passed.','less than two hours 表示不足两小时，不可能同时超过三小时。','measurement'),[Q('less than',1,1,'Less than two hours means?','under two hours','exactly two hours and one minute','more than three hours','less than 表示少于。'),Q('less than',2,1,'Why was the repair completed quickly?','the technician had found the damaged cable already','the technician had not looked for any cable','the repair required several days','提前找到问题缩短了维修时间。'),Q('less than',3,1,'Which amount is less than ten dollars?','$8.50','$10.00','$12.00','$8.50 小于十美元。'),Q('less than',4,1,'Less than is commonly followed by?','a number or amount being compared','a person’s surname only','a plural verb with no noun','less than 常接数字或数量。')]);
P('lessee','Lessee is formed from lease plus the recipient suffix -ee and names the person or organization renting property from its owner.',C('lessee.s1','租赁合同','The lessee signed the apartment contract and agreed to pay rent on the first day of each month.','承租人签署了公寓合同，并同意每月第一天交租。','The lessee signed the apartment contract / and agreed to pay rent / on the first day of each month.','lessee 指从业主处租用财产的一方；pay rent 表明承租义务。','签合同并支付房租的是承租人。'),M('The lessee owned the apartment and collected rent from the person who occupied it.','The lessee rented the apartment from its owner and paid the agreed rent.','拥有房产并收取租金的是出租方，不是 lessee。','meaning'),[Q('lessee',1,1,'A lessee is the person who?','rents property from an owner','owns the property and rents it out','writes laws for a legislature','lessee 指承租人。'),Q('lessee',2,1,'What did the lessee agree to do?','pay rent each month','teach a lecture every day','lend the apartment to the owner permanently','承租人同意按月支付租金。'),Q('lessee',3,1,'Which word is closest in meaning to lessee?','tenant','lessor','lender','tenant 与 lessee 同义。'),Q('lessee',4,1,'The suffix -ee in lessee marks?','the person receiving or holding the lease','the person making laws','a unit of length','-ee 常表示承受某动作或权利的人。','word-formation')]);
P('lessen','Lessen is formed from less plus the verb-forming ending -en and means become smaller or weaker, or make something so.',C('lessen.s1','风险与影响','The new drainage system lessened the flood risk for homes beside the river.','新的排水系统降低了河边住宅的洪水风险。','The new drainage system lessened the flood risk / for homes / beside the river.','lessen 可作及物动词表示使程度或影响变小；lessened 是过去式。','排水系统降低了洪水风险。'),M('The new barrier lessened the flood risk by allowing more water to enter every house.','The new barrier lessened the flood risk by directing water away from homes.','让更多洪水进入住宅会加重风险，不会减轻风险。','meaning'),[Q('lessen',1,1,'To lessen a risk is to?','reduce it','make it larger','turn it into a lecture','lessen 指使风险变小。'),Q('lessen',2,1,'What did the drainage system lessen?','the flood risk','the length of a lemon','the legality of the lease','排水系统降低了洪水风险。'),Q('lessen',3,1,'Which sentence uses lessen naturally?','The medicine lessened the pain.','The medicine lessened the pain by making it stronger.','The medicine was a lessen of pain.','药物减轻疼痛是自然用法。'),Q('lessen',4,1,'Lessen is related to which comparative?','less','least','lessor','lessen 与 less 同词族。')]);
P('lesser','Lesser is formed from less plus -er and means smaller in degree or importance; it is not normally used as a regular comparative adjective before than.',C('lesser.s1','选择与轻重','The board chose the lesser of two risks, accepting a small delay rather than exposing workers to danger.','董事会选择了两种风险中较小的一种，宁可接受轻微延误，也不让工人陷入危险。','The board chose the lesser of two risks / accepting a small delay / rather than exposing workers to danger.','the lesser of two 是固定比较结构，指两者中较小或较轻的一方。','董事会选择了危险性较小的方案。'),M('The board chose the lesser of two risks by selecting the option that posed the greater danger to workers.','The board chose the lesser risk by selecting the option that posed less danger to workers.','造成更大危险的方案不可能是 lesser risk。','meaning'),[Q('lesser',1,1,'The lesser risk is?','the smaller or less serious risk','the most dangerous possible risk','the longest stage of a trip','lesser 表示较小、较轻。'),Q('lesser',2,1,'Why did the board accept a delay?','it was a lesser risk than exposing workers to danger','it was more dangerous than the alternative','the board wanted a lengthy meeting','董事会选择了较小的风险。'),Q('lesser',3,1,'Which phrase is a common use?','the lesser of two evils','the lesser than of two evils','the leastly of two evils','常见表达是 the lesser of two evils。'),Q('lesser',4,1,'Lesser is closest in meaning to?','smaller or less important','legally required','extremely legible','lesser 可表示次要或较小。')]);
P('lesson','Lesson comes through Old French from Latin lectio, “a reading”; it can mean a teaching period, knowledge gained from experience, or a section of a textbook.',[C('lesson.s1','课程与学习','I have a piano lesson on Friday, so I practise the new piece every evening this week.','我星期五有钢琴课，所以这周每天晚上都练习新曲子。','I have a piano lesson on Friday / so I practise the new piece / every evening this week.','lesson.s1 指一段教授技能或学科的课程；a piano lesson 是常见搭配。','学生为即将到来的钢琴课练习。'),C('lesson.s2','经验与教训','The failed launch taught the engineers a lesson about testing batteries in cold weather.','发射失败给工程师们上了一课，让他们认识到要在寒冷天气测试电池。','The failed launch taught the engineers a lesson / about testing batteries / in cold weather.','lesson 可指从经历尤其是错误中获得的教训；teach someone a lesson 是常见搭配。','事故促使工程师总结出测试经验。'),C('lesson.s3','教材单元','Please read lesson five before the seminar so we can discuss the chapter’s examples.','请在研讨课前阅读第五课，这样我们就能讨论本章的例子。','Please read lesson five before the seminar / so we can discuss / the chapter’s examples.','lesson 也指课本中安排学习的一课；lesson five 是编号用法。','学生按教材单元提前阅读。')],M('The team learned no lesson from the failed launch and repeated the same battery mistake without testing it.','The team learned a lesson from the failed launch and tested the batteries in cold conditions next time.','重复相同失误且不采取改进，说明没有吸取教训。','meaning'),[Q('lesson',1,1,'A piano lesson is?','a period in which someone is taught a skill','a legal contract for renting a room','a support under a table','lesson.s1 指课程。'),Q('lesson',2,2,'A lesson learned from a failed launch is?','useful knowledge gained from experience','the fifth section of a textbook only','a person who leaves a school','lesson.s2 指经验教训。'),Q('lesson',3,3,'“Read lesson five” refers to?','a section of a textbook','a teacher’s punishment','a leg of a journey','lesson.s3 指教材中的一课。'),Q('lesson',4,2,'What did the engineers learn after the failed launch?','to test batteries in cold weather','to stop using any batteries forever','to leave the lecture room','事故让工程师认识到低温测试的重要性。')]);
P('lessor','Lessor is formed from lease with the agent suffix -or and names the person or company that rents property to another party.',C('lessor.s1','租赁与责任','The lessor agreed to repair the roof because the lease assigned structural maintenance to the property owner.','出租方同意修理屋顶，因为租约规定结构维护由房主负责。','The lessor agreed to repair the roof / because the lease assigned structural maintenance / to the property owner.','lessor 指把房屋或财产租给他人的一方；此处是房主。','合同把维修责任交给出租方。'),M('The lessor paid rent to the tenant every month for permission to live in the apartment.','The lessee paid rent to the lessor for permission to live in the apartment.','支付租金居住的是承租人 lessee；收取租金的是 lessor。','confusable'),[Q('lessor',1,1,'A lessor is the person who?','rents property to another person','rents property from an owner','teaches a class about law','lessor 指出租方。'),Q('lessor',2,1,'Who agreed to repair the roof?','the lessor, as property owner','the lessee, as tenant','the lecturer, as guest','例句中出租房屋一方负责屋顶维修。'),Q('lessor',3,1,'Which word is closest in meaning to lessor?','landlord','tenant','lender','landlord 可指 lessor。'),Q('lessor',4,1,'Which party usually pays rent to the lessor?','the lessee','the legislature','the lecturer','承租人向出租方支付租金。')]);
P('lest','Lest is an old formal conjunction used to introduce something feared and avoided, meaning “for fear that” or “so that ... not.”',[C('lest.s1','谨慎与避免','She spoke quietly lest she wake the baby sleeping in the next room.','她轻声说话，以免吵醒睡在隔壁房间的婴儿。','She spoke quietly / lest she wake the baby / sleeping in the next room.','lest.s1 引出想避免发生的事情；lest 后常用动词原形 wake。','轻声说话是为了避免婴儿醒来。',''),C('lest.s2','正式警示','He locked the window lest it should come loose during the storm.','他锁紧窗户，生怕暴风雨中窗户松开。','He locked the window / lest it should come loose / during the storm.','lest 也可接 should + 动词原形，表达对危险发生的担忧。','锁窗的目的是防止窗户松脱。','')],M('She spoke quietly lest she would wake the baby, using the formal conjunction with a future auxiliary.','She spoke quietly lest she wake the baby.','正式英语中 lest 后常用动词原形或 should + 原形，不用 would。','grammar'),[Q('lest',1,1,'Lest introduces something that?','is feared and one wants to prevent','has already happened and cannot change','is a lesson in a textbook','lest 表示唯恐某事发生。'),Q('lest',2,1,'Why did she speak quietly?','so that she would not wake the baby','to wake the baby immediately','to give the baby a lecture','她轻声说话是为了不吵醒婴儿。'),Q('lest',3,2,'Which construction is standard after lest?','lest it should come loose','lest it would come loose','lest it will came loose','lest it should + 动词原形是标准结构。'),Q('lest',4,1,'Lest is most common in?','formal writing','casual texting only','informal slang','lest 语体较正式。')]);
P('let','Let comes from Old English lǣtan, “allow or cause”; it can mean permit, make a suggestion with “let us,” rent out property, or suppose something for an argument.',[C('let.s1','允许与请求','The guard let the visitors enter after checking their tickets at the gate.','门卫检查游客的门票后让他们入内。','The guard let the visitors enter / after checking their tickets / at the gate.','let someone do something 表示允许某人做某事，后接不带 to 的动词原形 enter。','门卫许可游客进入。'),C('let.s2','建议与邀请','Let us begin with the first question and leave time for discussion at the end.','我们从第一个问题开始，最后留出讨论时间。','Let us begin with the first question / and leave time for discussion / at the end.','Let us 可用于提出包括说话人在内的建议；leave time 表示留出时间。','说话者邀请大家一起开始。'),C('let.s3','房屋出租','They let the spare room to a graduate student for the summer term.','他们把空房间出租给一名研究生，租期为夏季学期。','They let the spare room to a graduate student / for the summer term.','let 作动词可指出租房间或建筑；let something to someone 是英式用法。','房主把房间租给学生。'),C('let.s4','论证与假设','Let the price be twenty dollars, and we can compare the two plans using the same starting point.','假设价格是二十美元，这样我们就可以从同一起点比较两个方案。','Let the price be twenty dollars / and we can compare the two plans / using the same starting point.','论证中 let 可表示假设；let x be 是数学和学术常见格式。','先假定价格，再进行比较。')],M('The guide let the visitors to enter the gallery after checking their tickets.','The guide let the visitors enter the gallery after checking their tickets.','let 后接宾语和不带 to 的动词原形。','grammar'),[Q('let',1,1,'To let visitors enter means to?','allow them to go in','make them leave immediately','rent the gallery to them','let.s1 指允许进入。'),Q('let',2,2,'“Let us begin” is used to?','make a suggestion including the speaker','rent a room to someone','suppose a price for calculation','let us 常用于提出共同建议。'),Q('let',3,3,'In British English, “They let a room” means they?','rent it out to someone','borrow it from a tenant','teach a lesson there','let.s3 表示出租房间。'),Q('let',4,4,'“Let x be 5” means?','suppose x equals 5 for the argument','allow x to walk away','rent x to another person','let.s4 表示假设。')]);
P('let down','Let down is a phrasal verb meaning disappoint someone by failing to do what they expected or needed.',C('let down.s1','承诺与信任','The team let its supporters down when it cancelled the promised community event without warning.','球队没有提前通知就取消承诺的社区活动，让支持者失望了。','The team let its supporters down / when it cancelled the promised community event / without warning.','let someone down 是可分短语，指辜负或使某人失望；supporters 是宾语。','取消承诺活动让支持者失望。'),M('The team let its supporters down by keeping its promise and delivering the event exactly as planned.','The team pleased its supporters by keeping its promise and holding the event as planned.','兑现承诺并举办活动不会使支持者失望。','meaning'),[Q('let down',1,1,'To let someone down is to?','disappoint or fail them','allow them into a building','rent a room to them','let down 指使某人失望。'),Q('let down',2,1,'Why were the supporters let down?','the event was cancelled without warning','the event took place as promised','the team invited them to the event','承诺的活动被取消使支持者失望。'),Q('let down',3,1,'Which sentence uses let down correctly?','I promised to help and I will not let you down.','I let down the room to a student.','I let you to down.','let you down 是“让你失望”。'),Q('let down',4,1,'Let down is closest to?','disappoint','release','allow to stay','disappoint 与 let down 意义相近。')]);
P('let fall','Let fall combines let with fall and means allow an object to drop, often by releasing it or failing to hold it.',C('let fall.s1','动作与物品','She let the rope fall gently onto the ground instead of throwing it toward the workers.','她把绳子轻轻放到地上，而不是朝工人扔过去。','She let the rope fall gently onto the ground / instead of throwing it / toward the workers.','let something fall 表示让某物落下；let 后接宾语加不带 to 的动词原形。','绳子被松手放下，而不是抛向别人。'),M('He let the glass fall but caught it securely before it moved downward at all.','He let the glass fall and watched it drop to the floor.','若杯子被及时接住且没有下落，就没有让它掉下。','meaning'),[Q('let fall',1,1,'To let an object fall is to?','allow it to drop','keep it firmly in the hand','lend it to a lessee','let fall 指让物体落下。'),Q('let fall',2,1,'What did she do with the rope?','lowered it gently onto the ground','threw it toward the workers','used it as a legal lease','例句说明她把绳子轻轻放下。'),Q('let fall',3,1,'Which sentence is grammatical?','They let the package fall.','They let the package to fall.','They let fall the package to it.','let 后接宾语再接动词原形。'),Q('let fall',4,1,'Let fall is closest in meaning to?','allow to drop','make someone disappointed','allow someone to remain','let fall 指允许物体掉落。')]);
P('let loose','Let loose combines let with loose and means set something free or express feelings without restraint.',C('let loose.s1','释放与表达','After the final exam, the students let loose with music and dancing in the courtyard.','期末考试结束后，学生们在院子里尽情听音乐、跳舞放松。','After the final exam / the students let loose with music and dancing / in the courtyard.','let loose 可指放松约束、尽情表达；let loose with 后接释放的情绪或活动。','考试结束后学生们不再拘束，尽情庆祝。'),M('The handler let the dog loose by keeping it tied securely to a short chain inside the kennel.','The handler let the dog loose by unclipping its lead in the enclosed yard.','继续用短链拴住狗并未让它自由活动。','meaning'),[Q('let loose',1,1,'To let an animal loose is to?','set it free from restraint','tighten its leash','leave it in a lecture','let loose 指放开束缚。'),Q('let loose',2,1,'What did the students do after the exam?','celebrated freely with music and dancing','kept silent under strict rules','signed a lease for a classroom','他们考试后尽情庆祝。'),Q('let loose',3,1,'Which phrase fits?','let loose with a burst of laughter','let loose to the room for rent','let loose the lengthwise','let loose with 可表示尽情表达。'),Q('let loose',4,1,'Let loose is closest in meaning to?','unleash or release','disappoint','remain in place','unleash 与 let loose 意义相近。')]);
P('let stay','Let stay combines let with stay and means allow someone to remain in a place.',C('let stay.s1','住宿与许可','The neighbour let the stranded cyclist stay overnight until the repair shop opened in the morning.','邻居让被困的骑行者留宿一晚，直到修车店早晨开门。','The neighbour let the stranded cyclist stay overnight / until the repair shop opened / in the morning.','let someone stay 表示允许某人留下或留宿；stay 是不带 to 的动词原形。','邻居允许骑行者暂留过夜。'),M('The host let the cyclist stay overnight by asking him to leave immediately and locking the door.','The host let the cyclist stay overnight by offering a spare room.','要求马上离开与允许留宿相反。','meaning'),[Q('let stay',1,1,'To let someone stay is to?','allow them to remain','make them leave','rent a house from them','let stay 指允许留下。'),Q('let stay',2,1,'Why did the cyclist stay overnight?','the neighbour gave permission while repairs were unavailable','the neighbour ordered him to leave','the repair shop was open all night','邻居允许他暂时留宿。'),Q('let stay',3,1,'Which sentence uses let stay correctly?','Will you let me stay until morning?','Will you let me to stay until morning?','Will you let stay me until morning?','let 后接宾语和动词原形。'),Q('let stay',4,1,'Let stay is closest in meaning to?','allow someone to remain','let someone fall','let someone down','allow someone to remain 与 let stay 意义相同。')]);
P('lethal','Lethal comes from Latin letalis, “deadly,” from letum, “death”; it describes something capable of causing death.',C('lethal.s1','医学与安全','The laboratory kept the lethal chemical in a locked cabinet and required staff to wear protective equipment.','实验室把致命化学品锁在柜子里，并要求工作人员穿戴防护装备。','The laboratory kept the lethal chemical in a locked cabinet / and required staff / to wear protective equipment.','lethal 修饰 chemical，表示该物质足以致死；protective equipment 是安全措施。','危险物质致命，因此需要严密防护。'),M('The warning called the harmless dose lethal even though testing showed it could not injure or kill anyone.','The warning called the concentrated dose lethal because it could cause death.','已证明无害的剂量不能称为 lethal。','meaning'),[Q('lethal',1,1,'A lethal substance is able to?','cause death','make handwriting easy to read','reduce the length of a table','lethal 指足以致死的。'),Q('lethal',2,1,'How was the lethal chemical stored?','in a locked cabinet with protective rules','on an open table for children','inside a lettuce leaf','致命化学品被锁起并要求防护。'),Q('lethal',3,1,'Which phrase is natural?','a lethal dose','a lethal leisure','a lethal lesson five','a lethal dose 是自然搭配。'),Q('lethal',4,1,'Lethal is closest in meaning to?','deadly','lenient','legible','deadly 与 lethal 意义接近。')]);
P('lethargic','Lethargic comes from Greek lethargikos through Latin and describes someone lacking energy, feeling sleepy, or unwilling to act.',C('lethargic.s1','身体状态','After a sleepless night, Omar felt lethargic and struggled to focus during the morning lecture.','一夜没睡后，奥马尔感到无精打采，上午听讲时很难集中注意力。','After a sleepless night / Omar felt lethargic / and struggled to focus during the morning lecture.','lethargic 作表语形容人缺乏精力、困倦；after 引出疲倦原因。','缺觉让他疲乏、难以专注。'),M('Omar felt lethargic after sleeping well and running a race, yet the sentence said he was full of energy.','Omar felt lethargic after staying awake all night and struggling to focus.','无精打采与精力充沛相反；此处要与缺觉和难以专注相符。','meaning'),[Q('lethargic',1,1,'A lethargic person feels?','low in energy and slow to act','extremely alert and energetic','legally permitted to work','lethargic 指疲乏、无精打采。'),Q('lethargic',2,1,'Why did Omar feel lethargic?','he had not slept during the night','he had completed a long holiday','he had eaten a lemon','熬夜导致早上疲乏。'),Q('lethargic',3,1,'Which phrase is a natural collocation?','feel lethargic','lethargic a lease','lethargic with a letter','feel lethargic 是常见搭配。'),Q('lethargic',4,1,'Lethargic is the adjective related to?','lethargy','leisure','legislation','lethargic 的名词形式是 lethargy。')]);
P('lethargy','Lethargy comes from Greek lethargia and means a lack of energy or enthusiasm, or in medical contexts an unusual sleepiness.',C('lethargy.s1','精力与状态','A heavy lethargy settled over the office after the heating failed and the room became stiflingly warm.','暖气故障后房间闷热，办公室里的人都感到沉重的倦怠。','A heavy lethargy settled over the office / after the heating failed / and the room became stiflingly warm.','lethargy 是不可数名词，指缺乏精力或热情的状态；settled over 描述倦怠笼罩。','闷热的环境让人提不起精神。'),M('The hikers recovered from lethargy by becoming more tired, less interested, and unable to move.','The hikers recovered from lethargy after resting and regaining their energy.','恢复精力与继续变得更疲乏不是一回事。','meaning'),[Q('lethargy',1,1,'Lethargy is a state of?','low energy or unusual sleepiness','sharp alertness and excitement','legal authority','lethargy 指倦怠或嗜睡。'),Q('lethargy',2,1,'What caused the office lethargy?','the warm, uncomfortable room','a well-rested team in fresh air','a short lesson on letters','闷热环境使员工感到倦怠。'),Q('lethargy',3,1,'Which word is the adjective related to lethargy?','lethargic','lethally','leisure','lethargic 是形容词形式。'),Q('lethargy',4,1,'A feeling of lethargy may make someone?','slow and unwilling to act','eager to run a race','more legally qualified','倦怠会使人动作迟缓、不愿行动。')]);
P('letter','Letter comes from Old French lettre and Latin littera; it can mean a written message, an alphabetic symbol, the exact wording of a rule, or literature as a field.',[C('letter.s1','通信与家庭','Mina wrote a letter to her grandfather describing the new school and the friends she had made there.','米娜给祖父写了一封信，介绍新学校和在那里结交的朋友。','Mina wrote a letter to her grandfather / describing the new school / and the friends she had made there.','letter.s1 指寄给他人的书面信息；write a letter to someone 是常见搭配。','她通过书信向祖父传递消息。'),C('letter.s2','拼写与字母','The child traced each letter of her name before trying to write the whole word independently.','孩子先描摹名字里的每个字母，然后尝试独立写出整个单词。','The child traced each letter of her name / before trying to write / the whole word independently.','letter.s2 指代表语音的书写符号；each 后接单数 letter。','她逐个练习名字中的字母。'),C('letter.s3','法律与措辞','The landlord followed the letter of the lease but ignored its purpose of protecting the tenant from unsafe repairs.','房东拘泥于租约的字面条文，却忽视了保护租户免受不安全维修影响的宗旨。','The landlord followed the letter of the lease / but ignored its purpose / of protecting the tenant from unsafe repairs.','the letter of the law/agreement 指字面条文，常与其 purpose 或 spirit 对照。','例句区分了合同字面条文与保护租户的目的。'),C('letter.s4','文学与学术','As a woman of letters, the historian published essays, translations, and several influential books.','作为一位女文人，这位历史学家发表了散文、译作和几本有影响力的著作。','As a woman of letters / the historian published essays, translations, / and several influential books.','a person of letters 指文学或学术写作者；letters 在此用复数表示文学。','她从事散文、翻译和著述，体现文学义。')],M('The note said “meet at noon,” but the sender described it as a spoken lecture with no written message.','The note was a written letter telling the recipient to meet at noon.','书面便条是书面信息，不是没有书面内容的口头讲座。','meaning'),[Q('letter',1,1,'A letter sent to a relative is?','a written message','an alphabetic symbol','a level of a building','letter.s1 指书信。'),Q('letter',2,2,'In “the letter A,” letter means?','a written symbol for a speech sound','a mailed message','the purpose behind a law','letter.s2 指字母。'),Q('letter',3,3,'The letter of the law is?','its exact wording','a message delivered by post','a famous writer','letter.s3 指法律的字面条文。'),Q('letter',4,4,'A woman of letters is?','a literary or scholarly writer','a person who delivers mail only','a person who rents property','letter.s4 指文学或学术人士。')]);
P('letters','Letters is the plural of letter and here names written messages sent through the post.',C('letters.s1','邮件与通信','The archive preserved hundreds of letters written by nurses during the evacuation.','档案馆保存了数百封护士在撤离期间写下的信件。','The archive preserved hundreds of letters / written by nurses / during the evacuation.','letters.s1 指邮寄或写给他人的书信；hundreds of 后接复数。','多封护士写下的通信被存档。'),M('The archive described the letters as mailed messages, but showed only one letter and no others.','The archive preserved many letters, including messages from nurses during the evacuation.','复数 letters 指多封信，而不是只有一封。','plural'),[Q('letters',1,1,'Letters are?','written messages sent to people','a single alphabetic symbol only','the plural of lecturer','letters 指多封书信。'),Q('letters',2,1,'Who wrote the archived letters?','nurses during the evacuation','the lessor of the archive','a group of leeks','例句中信件由撤离期间的护士撰写。'),Q('letters',3,1,'What does letters mean in this dictionary entry?','plural written correspondence','alphabetic signs only','law-making institutions','词条当前义项是复数书信。'),Q('letters',4,1,'Which sentence uses letters as messages?','She kept the letters from her brother.','The word has six letters.','She studied arts and letters.','第一句中的 letters 是信件。')]);
P('lettuce','Lettuce comes from Old French letuse and Latin lactuca, named for the plant’s milky sap; it is a leafy vegetable commonly eaten raw.',C('lettuce.s1','饮食与蔬菜','The cook washed the lettuce leaves, dried them carefully, and added them to the salad just before serving.','厨师洗净生菜叶，仔细沥干水分，并在上菜前将它们加入沙拉。','The cook washed the lettuce leaves / dried them carefully / and added them to the salad just before serving.','lettuce 指可生食的绿叶蔬菜；lettuce leaves 是常见搭配。','生菜叶被洗净后加入沙拉。'),M('The salad recipe called for lettuce, but the cook added leather strips from an old jacket.','The salad recipe called for lettuce, so the cook added washed leafy lettuce.','皮革不是可食用的叶菜，不能替代生菜。','meaning'),[Q('lettuce',1,1,'Lettuce is a?','green leafy vegetable','large spotted wild cat','legal contract','lettuce 指生菜、莴苣。'),Q('lettuce',2,1,'How was the lettuce prepared?','washed and added to a salad','used to repair a leather bag','left on a lecture desk','例句中生菜被洗净后放入沙拉。'),Q('lettuce',3,1,'Lettuce is commonly eaten?','raw in salads','as a metal lens','in a legal lease','生菜常生食做沙拉。'),Q('lettuce',4,1,'Which collocation is natural?','lettuce leaves','lettuce legislation','lethargic lettuce down','lettuce leaves 是常见搭配。')]);
P('leukaemia','Leukaemia is the British spelling of a cancer involving abnormal white blood cells; its name combines Greek leukos, “white,” and haima, “blood.”',C('leukaemia.s1','医学与拼写','The hospital’s British report described how leukaemia treatment affected the patient’s blood-cell counts.','医院的英式报告描述了白血病治疗如何影响患者的血细胞计数。','The hospital’s British report described / how leukaemia treatment affected / the patient’s blood-cell counts.','leukaemia 是英式拼写，指白血病；报告讨论治疗对血细胞数量的影响。','疾病和血细胞变化的医学语境符合该词义。'),M('The report called it leukaemia, a disease of the bones that produces no abnormal blood cells.','The report called it leukaemia, a cancer involving abnormal white blood cells.','白血病涉及异常白细胞，不是与血液无关的骨病。','meaning'),[Q('leukaemia',1,1,'Leukaemia is a cancer involving abnormal?','white blood cells','letters in a legal document','leaves of lettuce','leukaemia 影响白细胞。'),Q('leukaemia',2,1,'Which spelling is British?','leukaemia','leukemia only','leukeamia','leukaemia 是常见英式拼写。'),Q('leukaemia',3,1,'What did the report examine?','treatment effects on blood-cell counts','the length of a lecture','the legal status of a lease','例句讨论治疗对血细胞计数的影响。'),Q('leukaemia',4,1,'What does the Greek element leukos mean?','white','law','long','leukos 意为“白”。','word-formation')]);
P('leukemia','Leukemia is the American spelling of leukaemia, a cancer in which abnormal white blood cells are produced in excess.',C('leukemia.s1','医学研究','The American study followed patients with leukemia for five years after treatment.','这项美国研究在治疗后对癌症患者进行了五年随访。','The American study followed patients with leukemia / for five years / after treatment.','leukemia 是美式拼写，指涉及异常白细胞的癌症；followed patients 表示随访患者。','研究跟踪患者治疗后的病情变化。'),M('The American report used leukemia for a condition that involved no blood cells and was not a cancer.','The American report used leukemia for a cancer involving abnormal white blood cells.','leukemia 指涉及异常白细胞的癌症，不能解释为无关疾病。','meaning'),[Q('leukemia',1,1,'Leukemia is the American spelling of?','leukaemia','lettuce','leisure','leukemia 与 leukaemia 是英美拼写变体。'),Q('leukemia',2,1,'What type of cells are involved?','abnormal white blood cells','letters in a book','cells in a lemon tree only','白血病涉及异常白细胞。'),Q('leukemia',3,1,'What did the American study do?','followed patients for five years','rented a room to patients','measured a lecturer’s speech','研究随访白血病患者五年。'),Q('leukemia',4,1,'Should leukemia and leukaemia be treated as different diseases?','no, they are spelling variants of the same disease','yes, one is a fruit and one a disease','yes, one affects only legs','它们是同一疾病的英美拼写变体。')]);
P('level','Level comes through Old French and Latin forms related to a small balance; it can mean height or amount, a standard, flat, make flat or aim, or speak frankly.',[C('level.s1','高度与数量','The water level in the reservoir fell after weeks without rain.','数周没有降雨后，水库水位下降了。','The water level in the reservoir fell / after weeks without rain.','level.s1 指某一高度或数量；water level 是常见搭配。','水库中的水面高度下降。'),C('level.s2','能力与标准','The course is designed for learners whose English is at an intermediate level.','这门课程面向英语达到中级水平的学习者。','The course is designed for learners / whose English is at an intermediate level.','level.s2 指技能或质量标准；at an intermediate level 表示中级水平。','课程按学习者的能力层次设计。'),C('level.s3','表面平整','Check that the shelf is level before placing the glass jars on it.','把玻璃罐放上去之前，先检查搁板是否平整。','Check that the shelf is level / before placing the glass jars / on it.','level 作形容词，表示表面平坦或水平；此处作表语。','水平搁板能稳稳放置玻璃罐。'),C('level.s4','整平与对准','Workers levelled the ground before building the ramp beside the entrance.','工人在入口旁建坡道前先把地面整平。','Workers levelled the ground / before building the ramp / beside the entrance.','level 作及物动词表示使地面平坦；levelled 是英式拼法。','施工前先整平地面。'),C('level.s5','坦率相告','I will level with you: the repair will cost more than the first estimate.','我坦白告诉你：维修费用会高于最初估价。','I will level with you / the repair will cost more / than the first estimate.','level with someone 是口语表达，意为坦率地告诉某人真相。','说话者直接说明实际维修费用。')],M('The water level rose after the reservoir lost water for weeks without any rain.','The water level fell after weeks without rain reduced the reservoir.','长期无雨导致水库水位下降，而不是上升。','meaning'),[Q('level',1,1,'The water level is?','the height of the water surface','the colour of the water','the amount of leather used','level.s1 指水面的高度。'),Q('level',2,2,'An intermediate level describes?','a standard of skill or ability','a flat ground surface','a legal owner','level.s2 指能力标准。'),Q('level',3,3,'If a shelf is level, it is?','flat and horizontal','very lengthy','legally binding','level.s3 表示平坦水平。'),Q('level',4,4,'To level the ground is to?','make the surface flat','measure a learner’s skill','tell someone a secret','level.s4 作动词表示整平地面。')]);
P('level off','Level off is a phrasal verb meaning stop rising or falling and remain steady at about the same level.',C('level off.s1','数据与趋势','After a rapid increase in spring, monthly sales levelled off at around five thousand units.','春季迅速增长后，月销售量稳定在约五千件。','After a rapid increase in spring / monthly sales levelled off / at around five thousand units.','level off 表示停止上升或下降并保持平稳；at around 给出稳定水平。','销量不再增长，维持在大约同一数值。'),M('Sales levelled off, but the graph continued to rise steeply every month without becoming stable.','Sales levelled off when the graph became nearly flat and stayed around five thousand units.','持续陡升说明尚未趋于平稳。','meaning'),[Q('level off',1,1,'When sales level off, they?','stop rising or falling and become steady','continue to rise steeply','fall to zero immediately','level off 指趋于平稳。'),Q('level off',2,1,'At what value did sales level off?','around five thousand units','at exactly zero units','at the length of a lecture','例句中销量稳定在约五千件。'),Q('level off',3,1,'Which phrase is closest in meaning to level off?','stabilize','lengthen','let down','stabilize 与 level off 意思相近。'),Q('level off',4,1,'What did sales do after increasing rapidly?','they became steady','they disappeared','they turned into a legal lease','快速增长后销量稳定下来。')]);

})();
